#!/usr/bin/env python3
from __future__ import annotations

import csv
import json
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Optional


REQUIRED_MODEL_COLUMNS = {
    "model_name",
    "backend",
    "model_ref",
    "language_mode",
    "enabled",
}


@dataclass(frozen=True)
class ModelSpec:
    model_name: str
    backend: str
    model_ref: str
    language_mode: str
    enabled: bool
    decoder_preset: str = ""
    batch_hint: str = ""
    notes: str = ""
    expected_sr: str = ""


def parse_env_file(env_path: Path) -> dict[str, str]:
    values: dict[str, str] = {}
    if not env_path.exists():
        return values
    for raw in env_path.read_text(encoding="utf-8", errors="ignore").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        k = k.strip()
        v = v.strip().strip('"').strip("'")
        if k:
            values[k] = v
    return values


def resolve_hf_token(repo_root: Path, env_var: str = "HF_TOKEN") -> str:
    direct = os.environ.get(env_var, "").strip()
    if direct:
        return direct

    # Keep fallback aliases for compatibility.
    for alias in ("HF_TOKEN", "HUGGINGFACE_TOKEN"):
        value = os.environ.get(alias, "").strip()
        if value:
            return value

    env_values = parse_env_file(repo_root / ".env")
    direct_file = env_values.get(env_var, "").strip()
    if direct_file:
        return direct_file
    for alias in ("HF_TOKEN", "HUGGINGFACE_TOKEN"):
        value = env_values.get(alias, "").strip()
        if value:
            return value
    return ""


def normalize_bool(value: Any, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in {"1", "true", "t", "yes", "y", "on"}:
        return True
    if text in {"0", "false", "f", "no", "n", "off"}:
        return False
    return default


def load_json(path: Path, default: Optional[dict] = None) -> dict:
    if default is None:
        default = {}
    if not path.exists():
        return dict(default)
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return dict(default)


def write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def ensure_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    return path


def run_cmd(cmd: list[str], *, cwd: Optional[Path] = None, env: Optional[dict[str, str]] = None) -> None:
    pretty = " ".join(cmd)
    print(f"$ {pretty}")
    p = subprocess.Popen(
        cmd,
        cwd=str(cwd) if cwd else None,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )
    assert p.stdout is not None
    for line in p.stdout:
        print(line, end="")
    rc = p.wait()
    if rc != 0:
        raise subprocess.CalledProcessError(rc, cmd)


def load_models_csv(csv_path: Path) -> list[ModelSpec]:
    if not csv_path.exists():
        raise FileNotFoundError(f"Model list CSV not found: {csv_path}")
    with csv_path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        headers = set(reader.fieldnames or [])
        missing = REQUIRED_MODEL_COLUMNS - headers
        if missing:
            raise ValueError(
                f"Missing required model list columns: {sorted(missing)}. Found: {sorted(headers)}"
            )

        out: list[ModelSpec] = []
        for idx, row in enumerate(reader, start=2):
            model_name = (row.get("model_name") or "").strip()
            backend = (row.get("backend") or "").strip().lower()
            model_ref = (row.get("model_ref") or "").strip()
            language_mode = (row.get("language_mode") or "").strip().lower()
            enabled = normalize_bool(row.get("enabled"), default=True)

            if not model_name:
                raise ValueError(f"Row {idx}: model_name is empty")
            if backend not in {"hf_transformers", "nemo_parakeet"}:
                raise ValueError(
                    f"Row {idx}: backend must be hf_transformers or nemo_parakeet, got '{backend}'"
                )
            if not model_ref:
                raise ValueError(f"Row {idx}: model_ref is empty")
            if not language_mode:
                raise ValueError(f"Row {idx}: language_mode is empty")

            out.append(
                ModelSpec(
                    model_name=model_name,
                    backend=backend,
                    model_ref=model_ref,
                    language_mode=language_mode,
                    enabled=enabled,
                    decoder_preset=(row.get("decoder_preset") or "").strip(),
                    batch_hint=(row.get("batch_hint") or "").strip(),
                    notes=(row.get("notes") or "").strip(),
                    expected_sr=(row.get("expected_sr") or "").strip(),
                )
            )

    return out


def split_models_by_backend(models: list[ModelSpec]) -> tuple[list[ModelSpec], list[ModelSpec]]:
    active = [m for m in models if m.enabled]
    hf_models = [m for m in active if m.backend == "hf_transformers"]
    nemo_models = [m for m in active if m.backend == "nemo_parakeet"]
    return hf_models, nemo_models


def beep_done() -> None:
    if os.name != "nt":
        return
    try:
        import winsound  # type: ignore

        winsound.Beep(1000, 300)
        winsound.Beep(1200, 300)
        winsound.Beep(1500, 500)
    except Exception:
        try:
            sys.stdout.write("\a")
            sys.stdout.flush()
        except Exception:
            pass

"""


i:\Whisper-training-env\Scripts\python.exe "i:\whisper-acft\common_segments_analyzer.py" --input-dir "i:\Transcriptions_patched_corrected" --state-file "i:\Transcriptions_patched_corrected\Most_common_segments_state.json" --top-k 250 --min-count 1 --workers 0 --output-json "i:\Transcriptions_patched_corrected\Most_common_segments_counts.json"


"""











import argparse
import json
from collections import Counter
from concurrent.futures import ProcessPoolExecutor, as_completed
from pathlib import Path
from typing import Iterable, Mapping, MutableMapping, Optional, Sequence, Tuple

from tqdm import tqdm


def extract_segments(payload: Mapping) -> Sequence[Mapping]:
    """
    Find Whisper/Groq verbose_json segments.

    Supported shapes (best-effort):
      {"groq_response": {"segments": [...]}}
      {"segments": [...]}
      {"response": {"segments": [...]}}
      {"result": {"segments": [...]}}
      {"data": {"segments": [...]}}

    Returns:
      sequence of segment mappings with at least start/end/text when valid.
    """
    response: MutableMapping = payload.get("groq_response") or {}
    segments = response.get("segments")
    if segments:
        return segments  # type: ignore[return-value]

    segments = payload.get("segments")
    if segments:
        return segments  # type: ignore[return-value]

    for key in ("response", "result", "data"):
        nested = payload.get(key)
        if isinstance(nested, Mapping) and nested.get("segments"):
            return nested.get("segments")  # type: ignore[return-value]

    raise ValueError("No segments found in JSON (expected segments / groq_response.segments).")


def normalize_text(text: str) -> str:
    """Trim and collapse whitespace to make comparisons consistent."""
    return " ".join((text or "").strip().split())


def process_file(path: Path) -> Tuple[str, Counter, Optional[str]]:
    """
    Read a single transcript JSON and return a Counter of normalized segment texts.
    Returns (path, counter, error_message_if_any).
    """
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001 - want to capture any decode issue
        return (str(path), Counter(), f"Failed to parse JSON: {exc}")

    try:
        segments = extract_segments(data)
    except Exception as exc:  # noqa: BLE001 - allow per-file errors without stopping
        return (str(path), Counter(), f"Failed to extract segments: {exc}")

    counter: Counter = Counter()
    for seg in segments:
        text = normalize_text(seg.get("text", ""))
        if text:
            counter[text] += 1
    return (str(path), counter, None)


def load_state(state_path: Path) -> Tuple[Counter, set]:
    if not state_path.exists():
        return Counter(), set()
    payload = json.loads(state_path.read_text(encoding="utf-8"))
    counts = Counter(payload.get("counts", {}))
    processed = set(payload.get("processed_files", []))
    return counts, processed


def save_state(state_path: Path, counts: Counter, processed: Iterable[str]) -> None:
    state_path.write_text(
        json.dumps(
            {
                "counts": counts,
                "processed_files": list(processed),
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )


def run(
    input_dir: Path,
    state_file: Optional[Path],
    top_k: int,
    min_count: int,
    workers: Optional[int],
    output_json: Optional[Path],
) -> None:
    counts, processed = load_state(state_file) if state_file else (Counter(), set())

    files = sorted(input_dir.glob("*.json"))
    remaining = [p for p in files if str(p) not in processed]
    if not remaining:
        print("No new JSON files to process.")
        return

    progress = tqdm(total=len(remaining), desc="Scanning transcripts", unit="file")
    warn_count = 0
    with ProcessPoolExecutor(max_workers=workers) as executor:
        futures = {executor.submit(process_file, path): path for path in remaining}
        for future in as_completed(futures):
            path_str, counter, err = future.result()
            if err:
                tqdm.write(f"[warn] {path_str}: {err}")
                warn_count += 1
            else:
                counts.update(counter)
                processed.add(path_str)
                if state_file:
                    save_state(state_file, counts, processed)
            progress.update(1)
    progress.close()

    sorted_items = counts.most_common()
    if output_json:
        output_json.write_text(
            json.dumps(sorted_items, ensure_ascii=False, indent=2), encoding="utf-8"
        )

    print(f"\nTop segments (warnings: {warn_count}):")
    for idx, (text, cnt) in enumerate(sorted_items[:top_k], start=1):
        if cnt < min_count:
            continue
        print(f"{idx:>3}. [{cnt}]: {text}")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Find most common transcript segments across JSON files."
    )
    parser.add_argument(
        "--input-dir",
        required=True,
        type=Path,
        help="Directory containing transcript JSON files.",
    )
    parser.add_argument(
        "--state-file",
        type=Path,
        default=None,
        help="Optional path to save progress for resuming.",
    )
    parser.add_argument(
        "--top-k",
