#!/usr/bin/env python3
"""Fix bad header silent chunks by resampling them to 16000 Hz"""

import os
import json
import soundfile as sf
from pathlib import Path
from tqdm import tqdm
import numpy as np

def resample_audio(audio_data, orig_sr, target_sr):
    """Resample audio data from orig_sr to target_sr"""
    try:
        from scipy.signal import resample_poly
        from math import gcd
        
        g = gcd(orig_sr, target_sr)
        up = target_sr // g
        down = orig_sr // g
        resampled = resample_poly(audio_data, up, down).astype(np.float32)
        return resampled
    except ImportError:
        print("Warning: scipy not available, cannot resample")
        return None

def fix_file(file_path):
    """Fix a single audio file by resampling to 16000 Hz if needed"""
    try:
        # Read the file
        audio_data, sr = sf.read(file_path, dtype="float32", always_2d=False)
        
        # Convert to mono if stereo
        if audio_data.ndim == 2:
            audio_data = audio_data.mean(axis=-1)
        
        # Check if resampling is needed
        if sr != 16000:
            print(f"Resampling {Path(file_path).name} from {sr} Hz to 16000 Hz")
            resampled = resample_audio(audio_data, sr, 16000)
            if resampled is None:
                return False, "scipy not available"
            
            # Save the resampled audio
            sf.write(file_path, resampled, 16000, subtype="PCM_16")
            return True, f"resampled from {sr} Hz"
        else:
            return True, "already correct"
            
    except Exception as e:
        return False, str(e)

def main():
    manifest_path = "I:/Record_chunks/train_manifest.jsonl"
    trained_path = "i:/Record_chunks/trained_stage1.jsonl"
    
    print("=" * 80)
    print("FIXING BAD HEADER SILENT CHUNKS")
    print("=" * 80)
    
    # Load trained files to skip them
    trained_files = set()
    if os.path.exists(trained_path):
        with open(trained_path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        row = json.loads(line)
                        ap = row.get("audio_path")
                        if ap:
                            trained_files.add(ap)
                    except:
                        pass
    
    print(f"Already trained files: {len(trained_files)}")
    
    # Find bad header files (silent chunks with wrong sample rate)
    bad_header_files = []
    
    print(f"\nScanning manifest for bad header silent chunks...")
    
    with open(manifest_path, "r", encoding="utf-8") as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
                
            try:
                row = json.loads(line)
                audio_path = row.get("audio_path")
                if not audio_path:
                    continue
                
                # Skip already trained files
                if audio_path in trained_files:
                    continue
                
                # Only process silent chunks
                if not row.get("is_silent", False):
                    continue
                
                # Check if file exists
                if not os.path.exists(audio_path):
                    continue
                
                # Check if it's a bad header file
                try:
                    info = sf.info(audio_path)
                    if info.samplerate != 16000:
                        bad_header_files.append(audio_path)
                    elif float(info.frames) / float(info.samplerate) > 30.0:
                        bad_header_files.append(audio_path)
                except:
                    bad_header_files.append(audio_path)
                    
            except Exception as e:
                print(f"Error parsing line {line_num}: {e}")
    
    print(f"Found {len(bad_header_files)} bad header silent chunks to fix")
    
    if not bad_header_files:
        print("No bad header files found!")
        return
    
    # Fix the files
    fixed = 0
    failed = 0
    
    print(f"\nFixing files...")
    for file_path in tqdm(bad_header_files, desc="Fixing files"):
        success, message = fix_file(file_path)
        if success:
            fixed += 1
        else:
            failed += 1
            print(f"Failed to fix {file_path}: {message}")
    
    print(f"\n" + "=" * 80)
    print("FIXING SUMMARY:")
    print(f"Files to fix: {len(bad_header_files)}")
    print(f"Successfully fixed: {fixed}")
    print(f"Failed to fix: {failed}")
    
    if failed == 0:
        print("\nAll bad header silent chunks have been fixed!")
        print("You can now re-run stage 13 training.")
    else:
        print(f"\n{failed} files could not be fixed. Check the errors above.")

if __name__ == "__main__":
    main()

from __future__ import annotations

import hashlib
import os
import shutil
import subprocess
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import requests

AUDIO_EXTS = {
    ".mp3", ".m4a", ".wav", ".flac", ".ogg", ".opus", ".webm", ".mp4", ".mpeg", ".mpga", ".aac"
}

GROQ_TRANSCRIBE_URL = "https://api.groq.com/openai/v1/audio/transcriptions"


@dataclass(frozen=True)
class Key:
    name: str
    value: str


class KeyPool:
    """Round-robin key pool with cooldown.

    Important: Groq rate limits apply at the organisation level, so multiple keys from the same
    organisation won't increase throughput. This is still useful if you genuinely have keys under
    different orgs/projects, or if you want failover.
    """

    def __init__(self, keys: Sequence[Key], default_cooldown: float = 60.0, max_backoff_factor: int = 8):
        if not keys:
            raise ValueError("KeyPool: no keys provided")
        self.keys = list(keys)
        self.default_cooldown = float(default_cooldown)
        self.max_backoff_factor = int(max_backoff_factor)
        self.idx = 0
        self.next_ok: Dict[str, float] = {k.name: 0.0 for k in self.keys}
        self.fail_streak: Dict[str, int] = {k.name: 0 for k in self.keys}

    def get(self) -> Key:
        now = time.time()
        for _ in range(len(self.keys)):
            k = self.keys[self.idx]
            self.idx = (self.idx + 1) % len(self.keys)
            if now >= self.next_ok[k.name]:
                return k
        # all keys cooling down -> wait for earliest
        soonest = min(self.next_ok.values())
        time.sleep(max(1.0, soonest - now))
        return self.get()

    def cooldown(self, key_name: str, retry_after: Optional[float] = None) -> None:
        self.fail_streak[key_name] += 1
        base = float(retry_after) if retry_after else float(self.default_cooldown)
        factor = min(self.max_backoff_factor, 2 ** (self.fail_streak[key_name] - 1))
        wait = base * factor
        self.next_ok[key_name] = time.time() + wait


def which_or_die(exe: str) -> str:
    p = shutil.which(exe)
    if not p:
        raise SystemExit(f"ERROR: '{exe}' not found on PATH.")
    return p


def sha256_file(path: Path, block: int = 1024 * 1024) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            b = f.read(block)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def list_audio_files(input_dir: Path, recursive: bool = True, exts: Optional[Sequence[str]] = None) -> List[Path]:
    ext_set = set((e.lower() if e.startswith(".") else "." + e.lower()) for e in (exts or AUDIO_EXTS))
    if recursive:
        files = [p for p in input_dir.rglob("*") if p.is_file() and p.suffix.lower() in ext_set]
    else:
        files = [p for p in input_dir.glob("*") if p.is_file() and p.suffix.lower() in ext_set]
    files.sort(key=lambda p: str(p).lower())
    return files


def ffmpeg_decode_check(ffmpeg_bin: str, audio_path: Path, seconds: float = 0.0) -> Tuple[bool, str]:
    cmd = [ffmpeg_bin, "-hide_banner", "-v", "error", "-i", str(audio_path)]
    if seconds and seconds > 0:
        cmd += ["-t", f"{seconds}"]
    cmd += ["-f", "null", "-"]

    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if p.returncode == 0:
        return True, ""
    err = (p.stderr or "").strip()
    return False, err[:2500]


def groq_transcribe_requests(
    audio_path: Path,
    api_key: str,
    model: str,
    language: Optional[str],
    prompt: Optional[str],
    temperature: float,
    response_format: str,
    timestamp_granularities: Sequence[str],
    timeout_s: float,
) -> requests.Response:

    headers = {"Authorization": f"Bearer {api_key}"}

    # multipart form; repeated keys need list-of-tuples
    data: List[Tuple[str, str]] = [
        ("model", model),
        ("response_format", response_format),
        ("temperature", str(float(temperature))),
    ]
    if language:
        data.append(("language", language))
    if prompt:
        data.append(("prompt", prompt))
    for g in timestamp_granularities:
        # Groq docs: timestamp_granularities requires verbose_json
        data.append(("timestamp_granularities[]", g))

    with audio_path.open("rb") as f:
        files = {"file": (audio_path.name, f)}
        r = requests.post(
            GROQ_TRANSCRIBE_URL,
            headers=headers,
            data=data,
            files=files,
            timeout=timeout_s,
        )
    return r


