@contextlib.contextmanager
def _suppress_stream_output(enabled: bool) -> Any:
    if not enabled:
        yield
        return
    with open(os.devnull, "w", encoding="utf-8") as devnull:
        with contextlib.redirect_stdout(devnull), contextlib.redirect_stderr(devnull):
            yield


def _extract_text(result_item: Any) -> str:
    if result_item is None:
        return ""
    if isinstance(result_item, str):
        return result_item
    if isinstance(result_item, dict):
        txt = result_item.get("text")
        return txt if isinstance(txt, str) else ""
    txt = getattr(result_item, "text", None)
    return txt if isinstance(txt, str) else ""


def _shorten(text: str, max_len: int = 160) -> str:
    text = " ".join(text.strip().split())
    if len(text) <= max_len:
        return text
    return text[: max_len - 3] + "..."


def _word_tokens(text: str) -> list[str]:
    return [tok for tok in text.strip().split() if tok]


def _token_key(token: str) -> str:
    key = re.sub(r"[^A-Za-z0-9]+", "", token).lower()
    return key if key else token.lower()


def _common_prefix_words(left: list[str], right: list[str]) -> list[str]:
    limit = min(len(left), len(right))
    idx = 0
    while idx < limit and _token_key(left[idx]) == _token_key(right[idx]):
        idx += 1
    return right[:idx]


@dataclass
class SpeedStats:
    chunks: int = 0
    total_audio_sec: float = 0.0
    total_infer_sec: float = 0.0
    min_infer_sec: float = float("inf")
    max_infer_sec: float = 0.0

    def add(self, audio_sec: float, infer_sec: float) -> None:
        self.chunks += 1
        self.total_audio_sec += audio_sec
        self.total_infer_sec += infer_sec
        if infer_sec < self.min_infer_sec:
            self.min_infer_sec = infer_sec
        if infer_sec > self.max_infer_sec:
            self.max_infer_sec = infer_sec

    def summary_line(self) -> str:
        if self.chunks == 0:
            return "chunks=0"
        avg_infer = self.total_infer_sec / self.chunks
        avg_audio = self.total_audio_sec / self.chunks
        avg_rtf = self.total_infer_sec / self.total_audio_sec if self.total_audio_sec > 0 else float("inf")
        avg_xrt = (1.0 / avg_rtf) if avg_rtf > 0 else float("inf")
        min_infer = self.min_infer_sec if self.min_infer_sec != float("inf") else 0.0
        return (
            f"chunks={self.chunks} | avg_audio={avg_audio:.2f}s | avg_infer={avg_infer:.2f}s | "
            f"avg_RTF={avg_rtf:.3f} | avg_xRealtime={avg_xrt:.2f}x | "
            f"min_infer={min_infer:.2f}s | max_infer={self.max_infer_sec:.2f}s"
        )


def _keyboard_listener(cmd_q: "queue.Queue[str]", stop_event: threading.Event) -> None:
    if os.name != "nt":
        return

    import msvcrt  # type: ignore

    while not stop_event.is_set():
        if msvcrt.kbhit():
            ch = msvcrt.getwch()
            if ch in ("\x00", "\xe0"):
                # Skip extended key second byte.
                if msvcrt.kbhit():
                    _ = msvcrt.getwch()
                continue
            if ch == " ":
                cmd_q.put("toggle")
            elif ch.lower() == "s":
                cmd_q.put("stats")
            elif ch.lower() == "q" or ch == "\x1b":
                cmd_q.put("quit")
                stop_event.set()
                return
        time.sleep(0.01)


def _require_deps(debug: bool) -> tuple[Any, Any, Any]:
    try:
        import numpy as np  # type: ignore
    except Exception as exc:
        raise SystemExit(
            "Missing dependency: numpy. Install with:\n"
            "python -m pip install numpy"
        ) from exc

    try:
        import sounddevice as sd  # type: ignore
    except Exception as exc:
        raise SystemExit(
            "Missing dependency: sounddevice. Install with:\n"
            "python -m pip install sounddevice"
        ) from exc

    try:
        if not debug:
            os.environ.setdefault("NEMO_LOG_LEVEL", "ERROR")
        import torch  # type: ignore
        import nemo.collections.asr as nemo_asr  # type: ignore
        if not debug:
            try:
                from nemo.utils import logging as nemo_logging  # type: ignore

                nemo_logging.set_verbosity(nemo_logging.ERROR)
            except Exception:
                pass
    except Exception as exc:
        raise SystemExit(
            "Missing dependency: NeMo ASR stack. Install with:\n"
            "python -m pip install \"nemo_toolkit[asr]>=2.4.0\" torch"
        ) from exc

    return np, sd, (torch, nemo_asr)


def _load_model(model_id: str, device_req: str, torch: Any, nemo_asr: Any, debug: bool) -> tuple[Any, str]:
    if device_req == "auto":
        device = "cuda" if torch.cuda.is_available() else "cpu"
    else:
        device = device_req
    if device == "cuda" and not torch.cuda.is_available():
        raise SystemExit("Requested CUDA, but torch.cuda.is_available() is False.")

    if debug:
        print(_cyan(f"Loading model: {model_id}"))
    with _suppress_stream_output(enabled=not debug):
        asr_model = nemo_asr.models.ASRModel.from_pretrained(model_name=model_id)
    asr_model = asr_model.to(device)
    asr_model.eval()
    return asr_model, device


def _transcribe_once(
    asr_model: Any,
    audio_input: Any,
    timestamps: bool,
    debug: bool,
    batch_size: int,
    num_workers: int,
) -> list[str]:
    kwargs: dict[str, Any] = {}
    if timestamps:
        kwargs["timestamps"] = True

    kwargs["batch_size"] = max(1, int(batch_size))
    kwargs["num_workers"] = max(0, int(num_workers))
    kwargs["verbose"] = bool(debug)
    kwargs["return_hypotheses"] = False

    with _suppress_stream_output(enabled=not debug):
        try:
            out = asr_model.transcribe(audio=audio_input, **kwargs)
        except TypeError:
            kwargs.pop("verbose", None)
            out = asr_model.transcribe(audio=audio_input, **kwargs)

    if isinstance(out, tuple) and out:
        out = out[0]
    if isinstance(out, list):
        return [_extract_text(item) for item in out]
    return [_extract_text(out)]


def _parse_args() -> argparse.Namespace:
    ap = argparse.ArgumentParser(
        description="Live speed test for nvidia/parakeet-tdt-0.6b-v3 with SPACE toggle."
    )
    ap.add_argument("--model_id", default="nvidia/parakeet-tdt-0.6b-v3")
    ap.add_argument("--device", choices=["auto", "cpu", "cuda"], default="auto")
    ap.add_argument("--sample_rate", type=int, default=16000)
    ap.add_argument("--chunk_secs", type=float, default=1.5)
    ap.add_argument("--left_context_secs", type=float, default=8.0)
    ap.add_argument("--right_context_secs", type=float, default=0.6)
    ap.add_argument("--block_secs", type=float, default=0.2)
    ap.add_argument("--infer_batch_size", type=int, default=1, help="NeMo transcribe batch_size")
    ap.add_argument("--infer_num_workers", type=int, default=0, help="NeMo transcribe num_workers")
    ap.add_argument("--mic_device", default=None, help="sounddevice input device id or name")
    ap.add_argument("--timestamps", action="store_true", help="Ask NeMo for timestamps (extra overhead)")
    ap.add_argument("--start_active", action="store_true", help="Start recognition active immediately")
    ap.add_argument("--warmup", action="store_true", default=True, help="Warm up one chunk before live loop")
    ap.add_argument("--no_warmup", dest="warmup", action="store_false")
    ap.add_argument("--debug", action="store_true", help="Show detailed logs and speed metrics")
    ap.add_argument("--list_devices", action="store_true")
    ap.add_argument("--max_chunks", type=int, default=0, help="Stop after N chunks (0 = run until quit)")
    ap.add_argument("--out_jsonl", default="", help="Optional JSONL file for per-chunk speed logs")
    return ap.parse_args()


def _normalize_device_arg(raw_value: Optional[str]) -> Any:
    if raw_value is None:
        return None
    txt = str(raw_value).strip()
    if not txt:
        return None
    if txt.lstrip("+-").isdigit():
        return int(txt)
    return raw_value


def main() -> int:
    args = _parse_args()

    if args.list_devices:
        try:
            import sounddevice as sd  # type: ignore
        except Exception as exc:
            raise SystemExit(
                "Missing dependency: sounddevice. Install with:\n"
                "python -m pip install sounddevice"
            ) from exc
        print(sd.query_devices())
        return 0

    np, sd, nemo_stack = _require_deps(debug=args.debug)
    torch, nemo_asr = nemo_stack

    if args.chunk_secs <= 0:
        raise SystemExit("--chunk_secs must be > 0.")
    if args.left_context_secs < 0:
        raise SystemExit("--left_context_secs must be >= 0.")
    if args.right_context_secs < 0:
        raise SystemExit("--right_context_secs must be >= 0.")
    if args.block_secs <= 0:
        raise SystemExit("--block_secs must be > 0.")
    if args.infer_batch_size <= 0:
        raise SystemExit("--infer_batch_size must be > 0.")
    if args.infer_num_workers < 0:
        raise SystemExit("--infer_num_workers must be >= 0.")

    # Ensure ANSI colors work in modern Windows terminals.
    if os.name == "nt":
        os.system("")

    asr_model, resolved_device = _load_model(args.model_id, args.device, torch, nemo_asr, debug=args.debug)
    if args.debug:
        print(_green(f"Model ready on device={resolved_device}"))
    mic_device = _normalize_device_arg(args.mic_device)

    sample_rate = int(args.sample_rate)
    chunk_samples = int(round(args.chunk_secs * sample_rate))
    left_context_samples = int(round(args.left_context_secs * sample_rate))
    right_context_samples = int(round(args.right_context_secs * sample_rate))
    block_samples = max(1, int(round(args.block_secs * sample_rate)))

    if chunk_samples < 1:
        raise SystemExit("Computed chunk_samples < 1. Check --chunk_secs and --sample_rate.")

    if args.warmup:
        if args.debug:
            print(_cyan("Running warmup pass..."))
        _ = _transcribe_once(
            asr_model=asr_model,
            audio_input=np.zeros(chunk_samples, dtype=np.float32),
            timestamps=False,
            debug=args.debug,
            batch_size=args.infer_batch_size,
            num_workers=args.infer_num_workers,
        )
        if args.debug:
            print(_green("Warmup done."))

    _beep_ready()

    out_jsonl_path: Optional[Path] = Path(args.out_jsonl).resolve() if args.out_jsonl else None
    if out_jsonl_path is not None:
        out_jsonl_path.parent.mkdir(parents=True, exist_ok=True)

    if args.debug:
        print("")
        print(_cyan("Controls: SPACE=toggle, S=stats, Q/ESC=quit"))
        print(_yellow(f"Initial state: {'ACTIVE' if args.start_active else 'INACTIVE'}"))
        print(
            _cyan(
                f"Streaming window: chunk={args.chunk_secs:.2f}s, "
                f"left_ctx={args.left_context_secs:.2f}s, right_ctx={args.right_context_secs:.2f}s"
            )
        )
        print("")
    else:
        print(
            f"Ready. SPACE=toggle, Q/ESC=quit, S=stats. "
            f"(chunk={args.chunk_secs:.1f}s, left={args.left_context_secs:.1f}s, right={args.right_context_secs:.1f}s)"
        )

    stop_event = threading.Event()
    cmd_q: "queue.Queue[str]" = queue.Queue()
    audio_q: "queue.Queue[tuple[Any, float]]" = queue.Queue(maxsize=256)

    dropped_blocks = {"count": 0}

    def audio_callback(indata: Any, frames: int, time_info: Any, status: Any) -> None:
        if status:
            # Keep callback lightweight and avoid noisy logs.
            pass
        try:
            audio_q.put_nowait((indata[:, 0].copy(), time.perf_counter()))
        except queue.Full:
            dropped_blocks["count"] += 1

    kb_thread = threading.Thread(target=_keyboard_listener, args=(cmd_q, stop_event), daemon=True)
    kb_thread.start()

    stats = SpeedStats()
    active = bool(args.start_active)
    chunk_idx = 0
    stream_buffer = np.zeros(0, dtype=np.float32)
    stream_base_sample = 0
    next_chunk_start_sample = 0
    committed_words: list[str] = []
    prev_window_words: Optional[list[str]] = None

    log_fh = None
    try:
        if out_jsonl_path is not None:
            log_fh = out_jsonl_path.open("a", encoding="utf-8")

        with sd.InputStream(
            samplerate=sample_rate,
            blocksize=block_samples,
            channels=1,
            dtype="float32",
            callback=audio_callback,
            device=mic_device,
        ):
            while not stop_event.is_set():
                while True:
                    try:
                        cmd = cmd_q.get_nowait()
                    except queue.Empty:
                        break

                    if cmd == "toggle":
                        active = not active
                        stream_buffer = np.zeros(0, dtype=np.float32)
                        stream_base_sample = 0
                        next_chunk_start_sample = 0
                        committed_words = []
                        prev_window_words = None
                        if args.debug:
                            state = _green("ACTIVE") if active else _yellow("INACTIVE")
                            print(f"{state} at {time.strftime('%H:%M:%S')}")
                        else:
                            _beep_toggle(active)
                    elif cmd == "stats":
                        print(_cyan(stats.summary_line()))
                    elif cmd == "quit":
                        stop_event.set()
                        break

                if stop_event.is_set():
                    break

                try:
                    block, block_end_ts = audio_q.get(timeout=0.1)
                except queue.Empty:
                    continue

                if not active:
                    continue

                stream_buffer = np.concatenate((stream_buffer, block), axis=0)
                available_end_sample = stream_base_sample + int(stream_buffer.shape[0])

                # Process chunks only when we have enough lookahead (right context).
                while available_end_sample >= (next_chunk_start_sample + chunk_samples + right_context_samples):
                    chunk_idx += 1
                    chunk_start_sample = next_chunk_start_sample
                    chunk_end_sample = chunk_start_sample + chunk_samples

                    window_start_sample = max(0, chunk_start_sample - left_context_samples)
                    window_end_sample = chunk_end_sample + right_context_samples

                    local_start = max(0, window_start_sample - stream_base_sample)
                    local_end = max(local_start, window_end_sample - stream_base_sample)
                    window_audio = stream_buffer[local_start:local_end]

                    samples_after_chunk = max(0, available_end_sample - chunk_end_sample)
                    chunk_end_ts = block_end_ts - (float(samples_after_chunk) / float(sample_rate))

                    infer_start = time.perf_counter()
                    texts = _transcribe_once(
                        asr_model=asr_model,
                        audio_input=window_audio,
                        timestamps=args.timestamps,
                        debug=args.debug,
                        batch_size=args.infer_batch_size,
                        num_workers=args.infer_num_workers,
                    )
                    infer_end = time.perf_counter()

                    text = texts[0] if texts else ""
                    infer_sec = infer_end - infer_start
                    chunk_audio_sec = float(chunk_samples) / float(sample_rate)
                    queue_lag = max(0.0, infer_start - chunk_end_ts)
                    rtf = infer_sec / chunk_audio_sec if chunk_audio_sec > 0 else float("inf")
                    xrt = (1.0 / rtf) if rtf > 0 else float("inf")

                    current_words = _word_tokens(text)
                    emitted_words: list[str] = []
                    if prev_window_words is not None:
                        stable_words = _common_prefix_words(prev_window_words, current_words)
                        if len(stable_words) > len(committed_words):
                            emitted_words = stable_words[len(committed_words) :]
                            committed_words.extend(emitted_words)
                    prev_window_words = current_words
                    emitted_text = " ".join(emitted_words).strip()

                    stats.add(chunk_audio_sec, infer_sec)

                    if args.debug:
                        print(
                            f"[{chunk_idx:05d}] "
                            f"audio={chunk_audio_sec:4.2f}s | infer={infer_sec:4.2f}s | "
                            f"RTF={rtf:5.3f} | xRealtime={xrt:4.2f}x | lag={queue_lag:4.2f}s | "
                            f"window={len(window_audio)/sample_rate:4.2f}s | "
                            f"emit={_shorten(emitted_text, 80)} | raw={_shorten(text, 120)}"
                        )
                    else:
                        if emitted_text:
                            print(emitted_text, flush=True)

                    if log_fh is not None:
                        payload = {
                            "chunk_index": chunk_idx,
                            "audio_sec": chunk_audio_sec,
                            "window_audio_sec": float(len(window_audio)) / float(sample_rate),
                            "infer_sec": infer_sec,
                            "rtf": rtf,
                            "x_realtime": xrt,
                            "queue_lag_sec": queue_lag,
                            "left_context_secs": float(args.left_context_secs),
                            "right_context_secs": float(args.right_context_secs),
                            "emitted_text": emitted_text,
                            "raw_text": text,
                            "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                        }
                        log_fh.write(json.dumps(payload, ensure_ascii=True) + "\n")
                        log_fh.flush()

                    next_chunk_start_sample += chunk_samples

                    # Keep only what we need for left-context on the next step.
                    keep_from_sample = max(0, next_chunk_start_sample - left_context_samples - block_samples)
                    if keep_from_sample > stream_base_sample:
                        drop_count = keep_from_sample - stream_base_sample
                        if drop_count >= int(stream_buffer.shape[0]):
                            stream_buffer = np.zeros(0, dtype=np.float32)
                        else:
                            stream_buffer = stream_buffer[drop_count:]
                        stream_base_sample = keep_from_sample
                        available_end_sample = stream_base_sample + int(stream_buffer.shape[0])

                    if args.max_chunks > 0 and chunk_idx >= args.max_chunks:
                        stop_event.set()
                        break

    except KeyboardInterrupt:
        stop_event.set()
    finally:
        # Flush tail text that may never have become stable before shutdown.
        if prev_window_words is not None and len(prev_window_words) > len(committed_words):
            tail_words = prev_window_words[len(committed_words) :]
            tail_text = " ".join(tail_words).strip()
            if tail_text:
                if args.debug:
                    print(_cyan(f"Final tail emit: {_shorten(tail_text, 120)}"))
                else:
                    print(tail_text, flush=True)

        if log_fh is not None:
            try:
                log_fh.close()
            except Exception:
                pass

    if args.debug:
        print("")
        print(_cyan("Final stats: " + stats.summary_line()))
        if dropped_blocks["count"] > 0:
            print(_yellow(f"Dropped audio callback blocks: {dropped_blocks['count']}"))
    _beep_done()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""
usage :

python c:\\Windows_software\\whisper-acft\\Record_harsha_identification_search_keywords_in_json.py --input-dir "i:\\P2GPT_google_drive\\My Drive\\Transcriptions" --state-file "i:\\P2GPT_google_drive\\My Drive\\Transcriptions\\keyword_search_state.json"

"""









import argparse
import json
import re
from concurrent.futures import ProcessPoolExecutor, as_completed
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Mapping, MutableMapping, Optional, Sequence, Set, Tuple

from tqdm import tqdm







def extract_segments(payload: Mapping) -> Sequence[Mapping]:
    """
    Best-effort extraction of Whisper/Groq verbose_json segments.
    Supports shapes:
      {"groq_response": {"segments": [...]}},
      {"segments": [...]},
      {"response": {"segments": [...]}},
      {"result": {"segments": [...]}},
      {"data": {"segments": [...]}},
    """
    response: MutableMapping = payload.get("groq_response") or {}
    segments = response.get("segments")
    if segments:
        return segments  # type: ignore[return-value]

    segments = payload.get("segments")
    if segments:
        return segments  # type: ignore[return-value]

    for key in ("response", "result", "data"):
        nested = payload.get(key)
        if isinstance(nested, Mapping) and nested.get("segments"):
            return nested.get("segments")  # type: ignore[return-value]

    return []


def normalize_text(text: str) -> str:
    return " ".join((text or "").strip().split())


def tokenize(text: str) -> List[str]:
    return [tok for tok in re.split(r"[^A-Za-z0-9-]+", text.lower()) if tok]


def levenshtein_distance(a: str, b: str, max_distance: int) -> int:
    """
    Compute Levenshtein distance with early exit when the running minimum
    exceeds max_distance (for speed).
    """
    if a == b:
        return 0
    if abs(len(a) - len(b)) > max_distance:
        return max_distance + 1

    # Ensure a is shorter
    if len(a) > len(b):
        a, b = b, a

    previous_row = list(range(len(a) + 1))
    for i, cb in enumerate(b, start=1):
        current_row = [i]
        min_row = current_row[0]
        for j, ca in enumerate(a, start=1):
            insertions = previous_row[j] + 1
            deletions = current_row[j - 1] + 1
            substitutions = previous_row[j - 1] + (ca != cb)
            current = min(insertions, deletions, substitutions)
            current_row.append(current)
            if current < min_row:
                min_row = current
        if min_row > max_distance:
            return max_distance + 1
        previous_row = current_row

    return previous_row[-1]


def collect_text_fields(payload: Mapping | list) -> List[str]:
    """
    Collect candidate text fields from various JSON shapes.
    Handles dict- and list-shaped payloads without crashing.
    """
    texts: List[str] = []

    # If payload is a list, scan list items that are dicts for string values.
    if isinstance(payload, list):
        for item in payload:
            if isinstance(item, Mapping):
                for v in item.values():
                    if isinstance(v, str):
                        texts.append(v)
            elif isinstance(item, str):
                texts.append(item)
        return [normalize_text(t) for t in texts if t]

    # Whole text if present
    groq_resp: MutableMapping = payload.get("groq_response") or {}
    main_text = groq_resp.get("text")
    if isinstance(main_text, str):
        texts.append(main_text)

    # Segment texts
    segments = extract_segments(payload)
    for seg in segments:
        text = seg.get("text")
        if isinstance(text, str):
            texts.append(text)

    # Fallback: all string fields at top level
    for value in payload.values():
        if isinstance(value, str):
            texts.append(value)
    return [normalize_text(t) for t in texts if t]


@dataclass
class MatchResult:
    path: str
    matched_keywords: Set[str]
    sample_tokens: Dict[str, Set[str]]
    error: Optional[str] = None


def process_file(path: Path, keywords: Sequence[str], max_distance: int) -> MatchResult:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        return MatchResult(path=str(path), matched_keywords=set(), sample_tokens={}, error=str(exc))

    texts = collect_text_fields(payload)
    if not texts:
        return MatchResult(path=str(path), matched_keywords=set(), sample_tokens={}, error="No text found")

    matched: Set[str] = set()
    samples: Dict[str, Set[str]] = {kw: set() for kw in keywords}
    for text in texts:
        for token in tokenize(text):
            for kw in keywords:
                dist = levenshtein_distance(token, kw, max_distance)
                if dist <= max_distance:
                    matched.add(kw)
                    samples[kw].add(token)
        # quick exit if all matched
        if len(matched) == len(keywords):
            break

    # Drop empty samples for cleaner output
    samples = {k: v for k, v in samples.items() if v}
    return MatchResult(path=str(path), matched_keywords=matched, sample_tokens=samples, error=None)


def save_state(state_path: Path, processed: Iterable[str], results: List[Dict]) -> None:
    state_path.write_text(
        json.dumps({"processed_files": list(processed), "results": results}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def load_state(state_path: Path) -> Tuple[Set[str], List[Dict]]:
    if not state_path.exists():
        return set(), []
    payload = json.loads(state_path.read_text(encoding="utf-8"))
    return set(payload.get("processed_files", [])), payload.get("results", [])


def run(
    input_dir: Path,
    keywords: Sequence[str],
    max_distance: int,
    workers: Optional[int],
    state_file: Optional[Path],
    output_json: Optional[Path],
) -> None:
    processed, results = load_state(state_file) if state_file else (set(), [])

    files = sorted(input_dir.glob("*.json"))
    remaining = [p for p in files if str(p) not in processed]
    if not remaining:
        print("No new JSON files to process.")
        return

    progress = tqdm(total=len(remaining), desc="Searching transcripts", unit="file")
    with ProcessPoolExecutor(max_workers=workers) as executor:
        futures = {
            executor.submit(process_file, path, keywords, max_distance): path for path in remaining
        }
        for future in as_completed(futures):
            result = future.result()
            if result.error:
                tqdm.write(f"[warn] {result.path}: {result.error}")
            elif result.matched_keywords:
                results.append(
                    {
                        "path": result.path,
                        "matched_keywords": sorted(result.matched_keywords),
                        "sample_tokens": {k: sorted(v) for k, v in result.sample_tokens.items()},
                    }
                )
            processed.add(result.path)
            if state_file:
                save_state(state_file, processed, results)
            progress.update(1)
    progress.close()

    matched_paths = {item["path"] for item in results}
    print(f"\nMatched {len(matched_paths)} files containing any of the keywords.")
    for idx, path in enumerate(sorted(matched_paths), start=1):
        print(f"{idx:>3}. {path}")

    if output_json:
        output_json.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
        print(f"Results written to {output_json}")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Fuzzy search transcript JSON files for keywords (Levenshtein)."
    )
    parser.add_argument(
        "--input-dir",
        required=True,
        type=Path,
        help="Directory containing transcript JSON files.",
    )
    parser.add_argument(
        "--keywords",
        nargs="+",
        default=["gutikonda", "8028267"],
        help="Keywords to search for (space-separated).",
    )
    parser.add_argument(
        "--max-distance",
        type=int,
        default=2,
        help="Maximum Levenshtein distance allowed for a match.",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=0,
        help="Number of processes to use (0 = auto).",
    )
    parser.add_argument(
        "--state-file",
        type=Path,
        default=None,
        help="Optional path to resume progress.",
    )
    parser.add_argument(
        "--output-json",
        type=Path,
        default=None,
        help="Optional path to write matched files and tokens.",
    )
    return parser


def main() -> None:
    parser = build_parser()
    args = parser.parse_args()
    workers = args.workers or None
    run(
        input_dir=args.input_dir,
        keywords=[kw.lower() for kw in args.keywords],
        max_distance=args.max_distance,
        workers=workers,
        state_file=args.state_file,
        output_json=args.output_json,
    )


if __name__ == "__main__":
    main()

from __future__ import annotations

import re
from typing import Optional


RUN_PREFIX = "RUN"
TOKEN_ORDER = ("k", "s", "b", "m", "a", "q", "c", "r", "id")


def slug_token(value: object, default: str = "unk") -> str:
    """Convert any token-like value to lowercase slug form."""
    if value is None:
        return default
    text = str(value).strip().lower()
    if not text:
        return default
    text = text.replace("_", "-")
    text = re.sub(r"[^a-z0-9-]+", "-", text)
    text = re.sub(r"-{2,}", "-", text).strip("-")
    return text or default


def _alias(value: object, mapping: dict[str, str], default: str = "unk") -> str:
    token = slug_token(value, default=default)
    return mapping.get(token, token)


def normalize_kind(value: object) -> str:
    return _alias(
        value,
        {
            "train-only": "train-only",
            "trainonly": "train-only",
            "train-eval": "train-eval",
            "traineval": "train-eval",
            "eval-only": "eval-only",
            "evalonly": "eval-only",
            "partial": "partial",
            "misc": "misc",
            "unk": "unk",
        },
        default="unk",
    )


def normalize_quant(value: object) -> str:
    return _alias(
        value,
        {
            "qat": "qat",
            "noqat": "noqat",
            "fp16": "noqat",
            "int8": "qat",
            "unk": "unk",
        },
        default="unk",
    )


def normalize_ctx(value: object) -> str:
    return _alias(
        value,
        {
            "dyn": "dyn",
            "dynamic": "dyn",
            "static": "static",
            "full": "static",
            "full-ctx": "static",
            "unk": "unk",
        },
        default="unk",
    )


def build_run_folder_name(
    *,
    kind: object,
    stage: object,
    base: object,
    method: object,
    adapter: object,
    quant: object,
    ctx: object,
    rows: object,
    run_id: object,
) -> str:
    """Build canonical run folder name."""
    fields = {
        "k": normalize_kind(kind),
        "s": slug_token(stage),
        "b": slug_token(base),
        "m": slug_token(method),
        "a": slug_token(adapter),
        "q": normalize_quant(quant),
        "c": normalize_ctx(ctx),
        "r": slug_token(rows),
        "id": slug_token(run_id),
    }
    parts = [f"{key}-{fields[key]}" for key in TOKEN_ORDER]
    return f"{RUN_PREFIX}__" + "__".join(parts)


def parse_run_folder_name(folder_name: str) -> Optional[dict[str, str]]:
    """Parse canonical run folder name to token dict."""
    if not folder_name or not folder_name.startswith(f"{RUN_PREFIX}__"):
        return None
    tokens = folder_name.split("__")[1:]
    if not tokens:
        return None
    parsed: dict[str, str] = {}
    for token in tokens:
        if "-" not in token:
            continue
        key, value = token.split("-", 1)
        if not key:
            continue
        parsed[key] = slug_token(value)
    if not all(key in parsed for key in TOKEN_ORDER):
        return None
    return {key: parsed[key] for key in TOKEN_ORDER}


def is_canonical_run_folder_name(folder_name: str) -> bool:
    return parse_run_folder_name(folder_name) is not None

"""stage17_main_utils_peft.py

PEFT/LoRA helper utilities for Stage 17 training.

Goal:
- Keep your existing Stage 17 script mostly unchanged.
- Enable LoRA (parameter-efficient fine-tuning) via env vars.
- Make resume logic work when the checkpoint folder contains only PEFT adapter weights.

Why LoRA here?
- Full fine-tuning can drift fast (and your WER can go up even when per-sample text looks OK).
- LoRA freezes the base weights and trains small low-rank matrices instead.
"""

from __future__ import annotations

import os
from typing import Iterable, Optional, Any

_PEFT_OVERRIDES: dict[str, Optional[Any]] = {
    "WHISPER_USE_PEFT": None,
    "WHISPER_LORA_R": None,
    "WHISPER_LORA_ALPHA": None,
    "WHISPER_LORA_DROPOUT": None,
    "WHISPER_LORA_TARGET_MODULES": None,
    "WHISPER_LORA_USE_DORA": None,
    "WHISPER_LORA_USE_RSLORA": None,
    "WHISPER_LORA_INIT": None,
}


def set_peft_overrides(**kwargs) -> None:
    """Set PEFT/LoRA defaults without using environment variables.

    Accepted keys:
    - WHISPER_USE_PEFT
    - WHISPER_LORA_R
    - WHISPER_LORA_ALPHA
    - WHISPER_LORA_DROPOUT
    - WHISPER_LORA_TARGET_MODULES
    - WHISPER_LORA_USE_DORA
    - WHISPER_LORA_USE_RSLORA
    - WHISPER_LORA_INIT
    """
    for key, value in kwargs.items():
        if key not in _PEFT_OVERRIDES:
            raise KeyError(f"Unknown PEFT override: {key}")
        _PEFT_OVERRIDES[key] = value


def _override(name: str):
    if name in _PEFT_OVERRIDES:
        return _PEFT_OVERRIDES[name]
    return None


def peft_is_enabled() -> bool:
    val = _override("WHISPER_USE_PEFT")
    if val is None:
        val = os.environ.get("WHISPER_USE_PEFT", "0")
    return str(val).strip() in ("1", "true", "True", "YES", "yes")


def _env_int(name: str, default: int) -> int:
    ov = _override(name)
    if ov is not None:
        try:
            return int(str(ov).strip())
        except Exception:
            return int(default)
    try:
        return int(str(os.environ.get(name, default)).strip())
    except Exception:
        return int(default)


def _env_float(name: str, default: float) -> float:
    ov = _override(name)
    if ov is not None:
        try:
            return float(str(ov).strip())
        except Exception:
            return float(default)
    try:
        return float(str(os.environ.get(name, default)).strip())
    except Exception:
        return float(default)


def _env_bool(name: str, default: bool) -> bool:
    ov = _override(name)
    if ov is not None:
        val = ov
    else:
        val = os.environ.get(name, None)
    if val is None:
        return bool(default)
    if isinstance(val, bool):
        return val
    s = str(val).strip().lower()
    if s in ("1", "true", "yes", "y", "on"):
        return True
    if s in ("0", "false", "no", "n", "off"):
        return False
    try:
        return bool(int(s))
    except Exception:
        return bool(default)


def _env_csv(name: str, default_csv: str) -> list[str]:
    ov = _override(name)
    if ov is not None:
        if isinstance(ov, (list, tuple)):
            return [str(p).strip() for p in ov if str(p).strip()]
        s = str(ov or "").strip()
    else:
        s = str(os.environ.get(name, default_csv) or "").strip()
    parts = [p.strip() for p in s.split(",")]
    return [p for p in parts if p]


def _env_lora_init(name: str, default: Any):
    ov = _override(name)
    if ov is not None:
        val = ov
    else:
        val = os.environ.get(name, None)
    if val is None or val == "":
        return default
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)) and not isinstance(val, bool):
        if int(val) == 0:
            return False
        if int(val) == 1:
            return True
    s = str(val).strip()
    if not s:
        return default
    low = s.lower()
    if low in ("1", "true", "yes", "y", "on"):
        return True
    if low in ("0", "false", "no", "n", "off"):
        return False
    return s


def is_peft_checkpoint_dir(path: str) -> bool:
    """Heuristic: PEFT adapter checkpoints contain adapter_config.json."""
    if not path or not os.path.isdir(path):
        return False
    return os.path.isfile(os.path.join(path, "adapter_config.json"))


def load_whisper_student_with_optional_peft(
    *,
    model_dir: Optional[str],
    base_model_id: str,
    generation_config=None,
    want_trainable_adapter: bool = False,
):
    """Load:
    - normal checkpoint dir (full weights) => WhisperForConditionalGeneration.from_pretrained(dir)
    - PEFT checkpoint dir (adapter weights only) => base model + PeftModel.from_pretrained
    - no dir => base model
    """
    from transformers import WhisperForConditionalGeneration

    if model_dir and os.path.isdir(model_dir):
        if is_peft_checkpoint_dir(model_dir):
            # Adapter-only checkpoint
            try:
                from peft import PeftModel
            except Exception as e:
                raise RuntimeError(
                    "Found a PEFT adapter checkpoint but 'peft' is not installed. "
                    "Install it in your env: pip install -U peft"
                ) from e

            print("Loading student from PEFT adapter checkpoint:", model_dir)
            base = WhisperForConditionalGeneration.from_pretrained(base_model_id, generation_config=generation_config)
            model = PeftModel.from_pretrained(base, model_dir, is_trainable=bool(want_trainable_adapter))
            return model

        print("Loading student from full checkpoint:", model_dir)
        return WhisperForConditionalGeneration.from_pretrained(model_dir, generation_config=generation_config)

    print("Loading student from base:", base_model_id)
    return WhisperForConditionalGeneration.from_pretrained(base_model_id, generation_config=generation_config)


def maybe_wrap_with_lora_peft(model):
    """If WHISPER_USE_PEFT=1, wrap model with LoRA using PEFT.

    Env knobs:
    - WHISPER_LORA_R (default 16)
    - WHISPER_LORA_ALPHA (default 32)
    - WHISPER_LORA_DROPOUT (default 0.05)
    - WHISPER_LORA_TARGET_MODULES (default "q_proj,v_proj")
    - WHISPER_LORA_USE_DORA (default 0)
    - WHISPER_LORA_USE_RSLORA (default 0)
    - WHISPER_LORA_INIT (default True; or "pissa"/"olora"/"loftq")
    """
    if not peft_is_enabled():
        return model

    try:
        from peft import LoraConfig, get_peft_model, TaskType
        from peft.peft_model import PeftModel
    except Exception as e:
        raise RuntimeError(
            "WHISPER_USE_PEFT=1 but 'peft' is not installed. "
            "Install it in your env: pip install -U peft"
        ) from e

    if isinstance(model, PeftModel):
        # Already wrapped (e.g., resumed from adapter checkpoint)
        return model

    r = _env_int("WHISPER_LORA_R", 16)
    alpha = _env_int("WHISPER_LORA_ALPHA", 32)
    dropout = _env_float("WHISPER_LORA_DROPOUT", 0.05)
    target_modules = _env_csv("WHISPER_LORA_TARGET_MODULES", "q_proj,v_proj")
    use_dora = _env_bool("WHISPER_LORA_USE_DORA", False)
    use_rslora = _env_bool("WHISPER_LORA_USE_RSLORA", False)
    init_lora_weights = _env_lora_init("WHISPER_LORA_INIT", True)

    cfg = LoraConfig(
        task_type=TaskType.SEQ_2_SEQ_LM,
        r=int(r),
        lora_alpha=int(alpha),
        lora_dropout=float(dropout),
        target_modules=target_modules,
        bias="none",
        use_dora=bool(use_dora),
        use_rslora=bool(use_rslora),
        init_lora_weights=init_lora_weights,
    )
    model = get_peft_model(model, cfg)

    # Helpful printout
    try:
        model.print_trainable_parameters()
    except Exception:
        pass
    return model


def iter_trainable_params(model) -> Iterable:
    """Only params with requires_grad=True."""
    for p in model.parameters():
        if getattr(p, "requires_grad", False):
            yield p

#!/usr/bin/env python3
r"""stage_19e_plot_eval_charts_advanced.py

Advanced visualization pack for Stage-19 target-vs-other sweep evaluations.

This script complements stage_19d by adding:
- Pareto/frontier views (quality vs separation vs model size)
- ECDF / survival distribution views for per-sample behavior
- Head-to-head dominance matrices between models
- Condition-rank and stability charts

Input
-----
Pass either:
- evaluation_results_futo_like_targetmix_sweep.json
or
- evaluation_per_sample_predictions_targetmix_sweep.json

Usage (Windows PowerShell)
-------------------------
C:\whisper-edge-eval-venv\Scripts\python.exe i:\whisper-acft\stage_19e_plot_eval_charts_advanced.py `
  --in_json "I:\Stage_19e_edge_eval_20260315\evaluation_per_sample_predictions_targetmix_sweep.json" `
  --out_dir "I:\Stage_19e_edge_eval_20260315\advanced_charts"
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


IMG_FORMAT = "png"
IMG_DPI = 220
IMG_QUALITY = 92


def _normalize_format(fmt: str) -> str:
    fmt = (fmt or "png").strip().lower()
    if fmt == "jpeg":
        return "jpg"
    return fmt


def _with_format(path: Path, fmt: str) -> Path:
    fmt = _normalize_format(fmt)
    ext = f".{fmt}"
    if path.suffix.lower() == ext:
        return path
    return path.with_suffix(ext)


def _save_fig(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    plt.tight_layout()
    fmt = _normalize_format(IMG_FORMAT)
    out = _with_format(path, fmt)
    kwargs = {"dpi": IMG_DPI, "format": "jpeg" if fmt == "jpg" else fmt}
    if fmt in {"jpg", "webp"}:
        kwargs["pil_kwargs"] = {"quality": int(IMG_QUALITY), "optimize": True}
    plt.savefig(out, **kwargs)
    plt.close()


def _beep() -> None:
    try:
        import winsound  # type: ignore

        winsound.Beep(900, 180)
        winsound.Beep(1200, 220)
    except Exception:
        print("\a", end="", flush=True)


def _short_model_name(name: str) -> str:
    base = str(name).replace("\\", "/").split("/")[-1]
    for char in ['<', '>', ':', '"', '|', '?', '*']:
        base = base.replace(char, "_")
    return base


def _display_model_name(name: str, max_len: int = 26) -> str:
    s = _short_model_name(name)
    if len(s) <= max_len:
        return s
    keep = max(4, (max_len - 3) // 2)
    return f"{s[:keep]}...{s[-keep:]}"


def _json_load(path: Path):
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def _extract_per_sample_meta(data: object) -> Optional[dict]:
    if isinstance(data, dict):
        if "__meta__" in data and isinstance(data.get("__meta__"), dict):
            meta = data.get("__meta__")
            if isinstance(meta.get("run_args"), dict):
                return meta.get("run_args")
            return meta
        if isinstance(data.get("run_args"), dict):
            return data.get("run_args")
        items = data.get("items") or data.get("samples")
        if isinstance(items, list):
            return _extract_per_sample_meta(items)
        return None
    if isinstance(data, list):
        for item in data:
            if not isinstance(item, dict):
                continue
            if "__meta__" in item and isinstance(item.get("__meta__"), dict):
                meta = item.get("__meta__")
                if isinstance(meta.get("run_args"), dict):
                    return meta.get("run_args")
                return meta
            if "run_args" in item and "mix_key" not in item and isinstance(item.get("run_args"), dict):
                return item.get("run_args")
    return None


def _resolve_results_json(in_path: Path, in_data: object) -> Optional[Path]:
    meta = _extract_per_sample_meta(in_data)
    if isinstance(meta, dict) and isinstance(meta.get("args"), dict):
        out_json = meta.get("args", {}).get("out_json")
        if out_json:
            p = Path(str(out_json))
            if p.exists():
                return p
    fallback = in_path.parent / "evaluation_results_futo_like_targetmix_sweep.json"
    if fallback.exists():
        return fallback
    return None


def _as_per_sample_rows(per_sample_payload: object) -> List[dict]:
    rows: List[dict] = []
    if isinstance(per_sample_payload, dict):
        rows = per_sample_payload.get("items") or per_sample_payload.get("samples") or []
        if not isinstance(rows, list):
            rows = []
        return [r for r in rows if isinstance(r, dict)]
    if isinstance(per_sample_payload, list):
        out = []
        for r in per_sample_payload:
            if not isinstance(r, dict):
                continue
            if "__meta__" in r and "mix_key" not in r:
                continue
            out.append(r)
        return out
    return rows


def _build_summary_df(results_data: dict) -> pd.DataFrame:
    rows = []
    for m in results_data.get("models", []) or []:
        if not isinstance(m, dict):
            continue
        overall = m.get("metrics_overall") or {}
        if not isinstance(overall, dict):
            overall = {}
        model = str(m.get("model", "unknown"))
        rows.append(
            {
                "model": model,
                "model_short": _short_model_name(model),
                "label": _display_model_name(model),
                "samples": overall.get("samples"),
                "wer_target": overall.get("wer_micro_target"),
                "wer_other": overall.get("wer_micro_other"),
                "cer_target": overall.get("cer_micro_target"),
                "cer_other": overall.get("cer_micro_other"),
                "win_rate": overall.get("win_rate_target_closer"),
                "margin": overall.get("avg_margin_other_minus_target"),
                "margin_cer": overall.get("avg_margin_cer_other_minus_target"),
                "param_count": overall.get("model_num_params"),
                "model_type": overall.get("model_type"),
            }
        )
    df = pd.DataFrame(rows)
    if df.empty:
        return df
    for c in ["samples", "wer_target", "wer_other", "cer_target", "cer_other", "win_rate", "margin", "margin_cer", "param_count"]:
        df[c] = pd.to_numeric(df[c], errors="coerce")
    df["param_m"] = df["param_count"] / 1_000_000.0
    return df


def _build_long_df(per_sample_rows: List[dict]) -> pd.DataFrame:
    long_rows: List[dict] = []
    for item in per_sample_rows:
        if not isinstance(item, dict):
            continue
        mix_key = item.get("mix_key")
        if not mix_key:
            continue
        cond_id = item.get("cond_id")
        snr_db = item.get("snr_db")
        overlap = item.get("overlap")
        preds = item.get("predictions") or {}
        if not isinstance(preds, dict):
            continue

        for model, pred in preds.items():
            if not isinstance(pred, dict):
                continue
            wt = pred.get("wer_target")
            wo = pred.get("wer_other")
            ct = pred.get("cer_target")
            co = pred.get("cer_other")
            margin = None
            margin_cer = None
            if wt is not None and wo is not None:
                try:
                    margin = float(wo) - float(wt)
                except Exception:
                    margin = None
            if ct is not None and co is not None:
                try:
                    margin_cer = float(co) - float(ct)
                except Exception:
                    margin_cer = None

            long_rows.append(
                {
                    "mix_key": str(mix_key),
                    "cond_id": str(cond_id),
                    "snr_db": snr_db,
                    "overlap": overlap,
                    "model": str(model),
                    "model_short": _short_model_name(str(model)),
                    "wer_target": wt,
                    "wer_other": wo,
                    "cer_target": ct,
                    "cer_other": co,
                    "margin": margin,
                    "margin_cer": margin_cer,
                    "win": pred.get("win_target_closer"),
                    "duration_sec_eval": pred.get("duration_sec_eval"),
                }
            )
    df = pd.DataFrame(long_rows)
    if df.empty:
        return df
    for c in ["snr_db", "overlap", "wer_target", "wer_other", "cer_target", "cer_other", "margin", "margin_cer", "duration_sec_eval"]:
        df[c] = pd.to_numeric(df[c], errors="coerce")
    df["win"] = df["win"].astype("boolean")
    return df


def _norm01(series: pd.Series, higher_is_better: bool) -> pd.Series:
    s = pd.to_numeric(series, errors="coerce")
    lo = s.min(skipna=True)
    hi = s.max(skipna=True)
    if pd.isna(lo) or pd.isna(hi) or hi == lo:
        return pd.Series(0.5, index=s.index)
    if higher_is_better:
        return (s - lo) / (hi - lo)
    return (hi - s) / (hi - lo)


def _ecdf(values: Iterable[float]) -> Tuple[np.ndarray, np.ndarray]:
    x = np.sort(np.asarray([v for v in values if pd.notna(v)], dtype=np.float64))
    if x.size == 0:
        return np.array([], dtype=np.float64), np.array([], dtype=np.float64)
    y = np.arange(1, x.size + 1, dtype=np.float64) / float(x.size)
    return x, y


def _survival(values: Iterable[float]) -> Tuple[np.ndarray, np.ndarray]:
    x, y = _ecdf(values)
    if x.size == 0:
        return x, y
    return x, 1.0 - y + (1.0 / float(x.size))


def _pareto_frontier(df: pd.DataFrame, x_col: str, y_col: str) -> pd.DataFrame:
    d = df[[x_col, y_col, "label"]].dropna().sort_values(x_col)
    keep_idx: List[int] = []
    best_y = -np.inf
    for idx, row in d.iterrows():
        y = float(row[y_col])
        if y > best_y:
            keep_idx.append(idx)
            best_y = y
    return d.loc[keep_idx].sort_values(x_col)


def _plot_pareto(df: pd.DataFrame, out_dir: Path) -> None:
    d = df.dropna(subset=["wer_target", "win_rate"]).copy()
    if d.empty:
        return
    plt.figure(figsize=(9, 6))
    size = np.where(pd.notna(d["param_m"]), np.clip(d["param_m"], 8, 400) * 2.2, 140.0)
    sc = plt.scatter(d["wer_target"], d["win_rate"], s=size, c=d["margin"], cmap="viridis", alpha=0.85, edgecolors="k", linewidths=0.4)
    frontier = _pareto_frontier(d, "wer_target", "win_rate")
    if len(frontier) >= 2:
        plt.plot(frontier["wer_target"], frontier["win_rate"], color="black", linewidth=1.6, linestyle="--", label="Pareto frontier")
        plt.legend(loc="best")
    for _, r in d.iterrows():
        plt.annotate(str(r["label"]), (float(r["wer_target"]), float(r["win_rate"])), fontsize=8)
    plt.xlabel("Target WER (lower is better)")
    plt.ylabel("Win rate target-closer (higher is better)")
    plt.title("Pareto view: target quality vs separation behavior")
    cb = plt.colorbar(sc)
    cb.set_label("Avg WER margin (other - target)")
    _save_fig(out_dir / "adv_01_pareto_wer_vs_winrate.png")

    if d["param_m"].notna().any():
        d2 = d.dropna(subset=["param_m"]).copy()
        if not d2.empty:
            plt.figure(figsize=(9, 6))
            plt.scatter(d2["param_m"], d2["wer_target"], c=d2["win_rate"], cmap="plasma", s=130, edgecolors="k", linewidths=0.4)
            for _, r in d2.iterrows():
                plt.annotate(str(r["label"]), (float(r["param_m"]), float(r["wer_target"])), fontsize=8)
            plt.xlabel("Model size (million parameters)")
            plt.ylabel("Target WER (lower is better)")
            plt.title("Size vs target WER (color = win rate)")
            plt.xscale("log")
            cb = plt.colorbar()
            cb.set_label("Win rate")
            _save_fig(out_dir / "adv_02_size_vs_target_wer.png")


def _plot_distribution_curves(df_long: pd.DataFrame, top_models: List[str], label_map: Dict[str, str], out_dir: Path) -> None:
    if df_long.empty:
        return

    plt.figure(figsize=(9, 6))
    for m in top_models:
        vals = df_long.loc[df_long["model"] == m, "wer_target"].dropna().values
        x, y = _ecdf(vals)
        if x.size == 0:
            continue
        plt.plot(x, y, linewidth=1.8, label=label_map.get(m, _display_model_name(m)))
    plt.xlabel("Per-sample target WER")
    plt.ylabel("ECDF")
    plt.title("ECDF of target WER (left/down is better)")
    plt.legend(fontsize=8)
    plt.grid(alpha=0.2)
    _save_fig(out_dir / "adv_03_ecdf_target_wer.png")

    plt.figure(figsize=(9, 6))
    for m in top_models:
        vals = df_long.loc[df_long["model"] == m, "margin"].dropna().values
        x, y = _survival(vals)
        if x.size == 0:
            continue
        plt.plot(x, y, linewidth=1.8, label=label_map.get(m, _display_model_name(m)))
    plt.xlabel("Per-sample WER margin (other - target)")
    plt.ylabel("Survival P(margin >= x)")
    plt.title("Tail behavior of separation margin (higher curve is better)")
    plt.legend(fontsize=8)
    plt.grid(alpha=0.2)
    _save_fig(out_dir / "adv_04_survival_margin.png")


def _pairwise_prob_matrix(pivot_df: pd.DataFrame, better: str = "lower") -> pd.DataFrame:
    models = list(pivot_df.columns)
    n = len(models)
    mat = np.full((n, n), np.nan, dtype=np.float64)
    for i, mi in enumerate(models):
        for j, mj in enumerate(models):
            if i == j:
                mat[i, j] = 0.5
                continue
            a = pd.to_numeric(pivot_df[mi], errors="coerce")
            b = pd.to_numeric(pivot_df[mj], errors="coerce")
            mask = a.notna() & b.notna()
            if mask.sum() == 0:
                continue
            if better == "lower":
                mat[i, j] = float((a[mask] < b[mask]).mean())
            else:
                mat[i, j] = float((a[mask] > b[mask]).mean())
    return pd.DataFrame(mat, index=models, columns=models)


def _plot_head_to_head(df_long: pd.DataFrame, model_order: List[str], label_map: Dict[str, str], out_dir: Path) -> None:
    if df_long.empty:
        return

    base = df_long[df_long["model"].isin(model_order)].copy()
    if base.empty:
        return

    piv_wt = base.pivot_table(index="mix_key", columns="model", values="wer_target", aggfunc="mean")
    piv_wt = piv_wt.reindex(columns=model_order)
    m_wt = _pairwise_prob_matrix(piv_wt, better="lower")

    piv_margin = base.pivot_table(index="mix_key", columns="model", values="margin", aggfunc="mean")
    piv_margin = piv_margin.reindex(columns=model_order)
    m_margin = _pairwise_prob_matrix(piv_margin, better="higher")

    def _draw(mat: pd.DataFrame, title: str, out_name: str) -> None:
        d = mat.values
        fig_w = max(8.5, 0.55 * len(mat.columns))
        fig_h = max(7.5, 0.55 * len(mat.index))
        plt.figure(figsize=(fig_w, fig_h))
        im = plt.imshow(d, aspect="auto", cmap="viridis", vmin=0.0, vmax=1.0)
        plt.colorbar(im, label="Probability")
        xlabels = [label_map.get(m, _display_model_name(m, max_len=18)) for m in mat.columns]
        ylabels = [label_map.get(m, _display_model_name(m, max_len=18)) for m in mat.index]
        plt.xticks(np.arange(len(xlabels)), xlabels, rotation=45, ha="right")
        plt.yticks(np.arange(len(ylabels)), ylabels)
        plt.xlabel("Compared model (column)")
        plt.ylabel("Reference model (row)")
        plt.title(title)
        for i in range(d.shape[0]):
            for j in range(d.shape[1]):
                if np.isnan(d[i, j]):
                    continue
                txt = f"{d[i, j]:.2f}"
                plt.text(j, i, txt, ha="center", va="center", fontsize=7, color="white")
        _save_fig(out_dir / out_name)

    _draw(
