#!/usr/bin/env python3
r"""stage_21_rank_target_severity_confidence_weighted.py

Rank TARGET files by "severity" of TARGET transcript vs prediction, using
confidence-weighted scoring (if confidence/logprob is present) or heuristics
when it is not.

Input:
  evaluation_per_sample_predictions_targetmix_sweep.json

Filtering:
  Uses ONLY the least overlap + highest SNR condition available in the input.

Output:
  JSON only (sorted by aggregate severity).

Usage (PowerShell):
  I:\Whisper-training-env\Scripts\python.exe i:\whisper-acft\stage_21_rank_target_severity_confidence_weighted.py `
    --in_json "I:\Stage_17_aug_futo_wer_rank64_dora_dyn_ctx_chkpts_small_en_26\evaluation_per_sample_predictions_targetmix_sweep.json" `
    --out_json "I:\Stage_17_aug_futo_wer_rank64_dora_dyn_ctx_chkpts_small_en_26\target_severity_ranked.json"
"""

from __future__ import annotations

import argparse
import json
import math
import re
from collections import Counter
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple


def _basic_whisperish_normalize(s: str) -> str:
    s = (s or "").strip().lower()
    s = s.replace("’", "'")
    s = re.sub(r"(?!\B'\b)[^a-z0-9\s']+", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    if s in ("<|nospeech|>", "<|nocaptions|>"):
        return ""
    return s


def _tokenize_words(s: str) -> List[str]:
    s = _basic_whisperish_normalize(s)
    if not s:
        return []
    return s.split()


def _char_tokens(s: str) -> List[str]:
    s = _basic_whisperish_normalize(s)
    return list(s)


def _edit_distance(a: List[str], b: List[str]) -> int:
    if not a:
        return len(b)
    if not b:
        return len(a)
    m, n = len(a), len(b)
    prev = list(range(n + 1))
    cur = [0] * (n + 1)
    for i in range(1, m + 1):
        cur[0] = i
        ai = a[i - 1]
        for j in range(1, n + 1):
            cost = 0 if ai == b[j - 1] else 1
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
        prev, cur = cur, prev
    return prev[n]


def _wer(ref: str, hyp: str) -> float:
    rt = _tokenize_words(ref)
    ht = _tokenize_words(hyp)
    if not rt:
        return 0.0 if not ht else 1.0
    return float(_edit_distance(rt, ht)) / float(len(rt))


def _cer(ref: str, hyp: str) -> float:
    rc = _char_tokens(ref)
    hc = _char_tokens(hyp)
    if not rc:
        return 0.0 if not hc else 1.0
    return float(_edit_distance(rc, hc)) / float(len(rc))


def _ngram_repeat_ratio(tokens: List[str], n: int) -> float:
    if len(tokens) < n + 1:
        return 0.0
    ngrams = [tuple(tokens[i : i + n]) for i in range(len(tokens) - n + 1)]
    counts = Counter(ngrams)
    repeats = sum(c - 1 for c in counts.values() if c > 1)
    return float(repeats) / float(max(1, len(ngrams)))


def _repetition_penalty(tokens: List[str]) -> float:
    if len(tokens) < 4:
        return 0.0
    rep2 = _ngram_repeat_ratio(tokens, 2)
    rep3 = _ngram_repeat_ratio(tokens, 3)
    return min(1.0, 0.5 * rep2 + 0.5 * rep3)


def _length_penalty(ref_tokens: List[str], hyp_tokens: List[str]) -> float:
    if not ref_tokens:
        return 0.0 if not hyp_tokens else 1.0
    diff = abs(len(hyp_tokens) - len(ref_tokens))
    return min(1.0, float(diff) / float(max(1, len(ref_tokens))))


def _extract_confidence(pred_entry: Dict[str, Any]) -> Optional[Tuple[str, float]]:
    for key in (
        "avg_logprob",
        "logprob",
        "avg_logprob_whisper",
        "confidence",
        "avg_confidence",
        "prob",
        "avg_prob",
    ):
        if key in pred_entry:
            try:
                return key, float(pred_entry.get(key))
            except Exception:
                continue
    return None


def _normalize_confidence(key: str, val: float) -> float:
    if "logprob" in key:
        try:
            return float(max(0.0, min(1.0, math.exp(val))))
        except Exception:
            return 0.0
    if val > 1.0 and val <= 100.0:
        return float(max(0.0, min(1.0, val / 100.0)))
    return float(max(0.0, min(1.0, val)))


def _compute_severity(
    *,
    pred_entry: Dict[str, Any],
    target_ref: str,
    pred: str,
    wer_weight: float,
    cer_weight: float,
    len_weight: float,
    rep_weight: float,
    cap_weight: float,
    conf_weight: float,
) -> Dict[str, Any]:
    wer = pred_entry.get("wer_target")
    cer = pred_entry.get("cer_target")
    if wer is None:
        wer = _wer(target_ref, pred)
    if cer is None:
        cer = _cer(target_ref, pred)
    base_error = (float(wer_weight) * float(wer)) + (float(cer_weight) * float(cer))

    tokens_ref = _tokenize_words(target_ref)
    tokens_pred = _tokenize_words(pred)
    len_pen = _length_penalty(tokens_ref, tokens_pred)
    rep_pen = _repetition_penalty(tokens_pred)
    cap_pen = 1.0 if bool(pred_entry.get("likely_hit_max_token_cap")) else 0.0

    conf = _extract_confidence(pred_entry)
    if conf is not None:
        conf_norm = _normalize_confidence(conf[0], conf[1])
        multiplier = 1.0 + float(conf_weight) * conf_norm
        used_mode = "confidence"
        conf_payload = {"key": conf[0], "value": conf[1], "normalized": conf_norm}
        len_pen_used, rep_pen_used, cap_pen_used = 0.0, 0.0, 0.0
    else:
        multiplier = 1.0 + (float(len_weight) * len_pen) + (float(rep_weight) * rep_pen) + (float(cap_weight) * cap_pen)
        used_mode = "heuristic"
        conf_payload = None
        len_pen_used, rep_pen_used, cap_pen_used = len_pen, rep_pen, cap_pen

    severity = base_error * multiplier
    return {
        "severity": severity,
        "base_error": base_error,
        "wer_target": float(wer),
        "cer_target": float(cer),
        "mode": used_mode,
        "confidence": conf_payload,
        "len_penalty": len_pen_used,
        "rep_penalty": rep_pen_used,
        "cap_penalty": cap_pen_used,
        "multiplier": multiplier,
        "pred_tokens": len(tokens_pred),
        "ref_tokens": len(tokens_ref),
    }


def _iter_items(data: Any) -> Iterable[Dict[str, Any]]:
    if isinstance(data, dict):
        items = data.get("items") or data.get("samples")
        if isinstance(items, list):
            for it in items:
                if isinstance(it, dict) and "predictions" in it:
                    yield it
            return
    if isinstance(data, list):
        for it in data:
            if not isinstance(it, dict):
                continue
            if "__meta__" in it:
                continue
            if "run_args" in it and "mix_key" not in it:
                continue
            if "predictions" in it:
                yield it


def _select_condition(items: List[Dict[str, Any]]) -> Tuple[Optional[float], Optional[float]]:
    overlaps: List[float] = []
    snrs: List[float] = []
    for it in items:
        ov = it.get("overlap", None)
        snr = it.get("snr_db", None)
        try:
            if ov is not None:
                overlaps.append(float(ov))
        except Exception:
            pass
        try:
            if snr is not None:
                snrs.append(float(snr))
        except Exception:
            pass
    min_ov = min(overlaps) if overlaps else None
    max_snr = max(snrs) if snrs else None
    return min_ov, max_snr


def _aggregate(values: List[float], mode: str) -> Optional[float]:
    if not values:
        return None
    vals = sorted(values)
    if mode == "max":
        return max(vals)
    if mode == "mean":
        return float(sum(vals)) / float(len(vals))
    if mode == "median":
        mid = len(vals) // 2
        if len(vals) % 2 == 1:
            return float(vals[mid])
        return float(vals[mid - 1] + vals[mid]) / 2.0
    if mode == "p90":
        idx = int(math.ceil(0.9 * len(vals))) - 1
        idx = max(0, min(idx, len(vals) - 1))
        return float(vals[idx])
    return max(vals)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--in_json", required=True)
    ap.add_argument("--out_json", required=True)
    ap.add_argument("--aggregate", default="max", choices=["max", "mean", "median", "p90"])
    ap.add_argument("--wer_weight", type=float, default=0.7)
    ap.add_argument("--cer_weight", type=float, default=0.3)
    ap.add_argument("--len_weight", type=float, default=0.4)
    ap.add_argument("--rep_weight", type=float, default=0.4)
    ap.add_argument("--cap_weight", type=float, default=0.2)
    ap.add_argument("--conf_weight", type=float, default=0.5)
    args = ap.parse_args()

    in_path = Path(args.in_json)
    out_path = Path(args.out_json)

    data = json.loads(in_path.read_text(encoding="utf-8"))
    items = list(_iter_items(data))
    if not items:
        raise SystemExit("No per-sample predictions found in input JSON.")

    min_overlap, max_snr = _select_condition(items)
    filtered: List[Dict[str, Any]] = []
    for it in items:
        try:
            snr_val = float(it.get("snr_db")) if it.get("snr_db") is not None else None
        except Exception:
            snr_val = None
        try:
            ov_val = float(it.get("overlap")) if it.get("overlap") is not None else None
        except Exception:
            ov_val = None

        if max_snr is not None and snr_val is not None and snr_val != max_snr:
            continue
        if min_overlap is not None and ov_val is not None and ov_val != min_overlap:
            continue
        filtered.append(it)

    if not filtered:
        raise SystemExit("No samples matched the least-overlap + highest-SNR filter.")

    # Group by target audio path; take worst per model across pairs for that target.
    targets: Dict[str, Dict[str, Any]] = {}
    for it in filtered:
        tpath = str(it.get("target_audio_path") or "")
        if not tpath:
            continue
        target_ref = it.get("target_reference") or it.get("target_ref") or ""
        preds = it.get("predictions", {})
        if not isinstance(preds, dict):
            continue

        tgt = targets.setdefault(
            tpath,
            {
                "target_audio_path": tpath,
                "target_reference": target_ref,
                "per_model": {},
            },
        )
        if not tgt.get("target_reference") and target_ref:
            tgt["target_reference"] = target_ref

        for model_name, pred_entry in preds.items():
            if not isinstance(pred_entry, dict):
                continue
            pred = pred_entry.get("pred", "") or ""
            sev = _compute_severity(
                pred_entry=pred_entry,
                target_ref=str(target_ref),
                pred=str(pred),
                wer_weight=float(args.wer_weight),
                cer_weight=float(args.cer_weight),
                len_weight=float(args.len_weight),
                rep_weight=float(args.rep_weight),
                cap_weight=float(args.cap_weight),
                conf_weight=float(args.conf_weight),
            )

            existing = tgt["per_model"].get(model_name)
            if existing is None or sev["severity"] > existing.get("severity", -1):
                tgt["per_model"][model_name] = {
                    "model": model_name,
                    "severity": sev["severity"],
                    "base_error": sev["base_error"],
                    "wer_target": sev["wer_target"],
                    "cer_target": sev["cer_target"],
                    "mode": sev["mode"],
                    "confidence": sev["confidence"],
                    "len_penalty": sev["len_penalty"],
                    "rep_penalty": sev["rep_penalty"],
                    "cap_penalty": sev["cap_penalty"],
                    "multiplier": sev["multiplier"],
                    "pred_tokens": sev["pred_tokens"],
                    "ref_tokens": sev["ref_tokens"],
                    "pred": pred,
                    "mix_key": it.get("mix_key"),
                    "snr_db": it.get("snr_db"),
                    "overlap": it.get("overlap"),
                    "other_audio_path": it.get("other_audio_path"),
                    "other_reference": it.get("other_reference") or it.get("other_ref"),
                }

    output_items: List[Dict[str, Any]] = []
    for tpath, rec in targets.items():
        per_model = list(rec.get("per_model", {}).values())
        severities = [float(x.get("severity")) for x in per_model if x.get("severity") is not None]
        agg = _aggregate(severities, str(args.aggregate))
        if agg is None:
            continue
        output_items.append(
            {
                "target_audio_path": tpath,
                "target_reference": rec.get("target_reference", ""),
                "severity_aggregate": agg,
                "aggregate_mode": str(args.aggregate),
                "per_model": sorted(per_model, key=lambda x: float(x.get("severity", 0.0)), reverse=True),
            }
        )

    output_items.sort(key=lambda x: float(x.get("severity_aggregate", 0.0)), reverse=True)

    out_obj = {
        "meta": {
            "input_json": str(in_path),
            "selected_overlap": min_overlap,
            "selected_snr_db": max_snr,
            "aggregate": str(args.aggregate),
            "weights": {
                "wer_weight": float(args.wer_weight),
                "cer_weight": float(args.cer_weight),
                "len_weight": float(args.len_weight),
                "rep_weight": float(args.rep_weight),
                "cap_weight": float(args.cap_weight),
                "conf_weight": float(args.conf_weight),
            },
            "targets": len(output_items),
            "filtered_pairs": len(filtered),
            "total_pairs": len(items),
        },
        "items": output_items,
    }

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(out_obj, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Wrote: {out_path}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
r"""stage_21b_apply_corrections_to_per_sample_predictions.py

Apply corrected TARGET transcripts from target_severity_ranked.json
back into evaluation_per_sample_predictions_targetmix_sweep.json files.

Usage (PowerShell):
  I:\Whisper-training-env\Scripts\python.exe i:\whisper-acft\stage_21b_apply_corrections_to_per_sample_predictions.py `
    --corrections_json "I:\Stage_17_aug_futo_wer_rank32_dora_dyn_ctx_chkpts_small_en_25\target_severity_ranked.json" `
    --in_jsons "I:\Stage_17_aug_futo_wer_rank32_dora_dyn_ctx_chkpts_small_en_25\evaluation_per_sample_predictions_targetmix_sweep.json"
"""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple


def canonical_audio_key(p: str) -> str:
    if not p:
        return ""
    return os.path.normpath(p).replace("\\", "/").lower()


def _skip_ws(text: str, i: int) -> int:
    n = len(text)
    while i < n and text[i].isspace():
        i += 1
    return i


def _best_effort_parse_array(text: str) -> List[Any]:
    items: List[Any] = []
    dec = json.JSONDecoder()
    i = _skip_ws(text, 0)
    if i >= len(text) or text[i] != "[":
        return items
    i += 1
    while True:
        i = _skip_ws(text, i)
        if i >= len(text):
            break
        if text[i] == "]":
            break
        try:
            obj, j = dec.raw_decode(text, i)
            items.append(obj)
            i = _skip_ws(text, j)
            if i < len(text) and text[i] == ",":
                i += 1
                continue
            if i < len(text) and text[i] == "]":
                break
        except json.JSONDecodeError:
            break
    return items


def load_json_any(path: Path) -> Any:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        print(f"[warn] JSONDecodeError: {e.msg} at line {e.lineno} col {e.colno}")
        text = path.read_text(encoding="utf-8", errors="replace")
        items = _best_effort_parse_array(text)
        if items:
            print(f"[warn] Proceeding with best-effort parse: {len(items)} items recovered.")
            return items
        raise


def write_json(path: Path, obj: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    tmp.replace(path)


def _extract_items(root: Any) -> Tuple[List[Dict[str, Any]], str]:
    if isinstance(root, dict):
        items = root.get("items")
        if isinstance(items, list):
            return [x for x in items if isinstance(x, dict)], "dict_items"
        items = root.get("samples")
        if isinstance(items, list):
            return [x for x in items if isinstance(x, dict)], "dict_samples"
    if isinstance(root, list):
        return [x for x in root if isinstance(x, dict)], "list"
    return [], "unknown"


def _extract_corrected_map(corrections_root: Any) -> Tuple[Dict[str, str], Dict[str, Any]]:
    items, _ = _extract_items(corrections_root)
    corrected: Dict[str, str] = {}
    conflicts = 0
    total = 0
    for item in items:
        if item.get("__meta__"):
            continue
        path = item.get("target_audio_path") or item.get("target_path")
        if not isinstance(path, str) or not path.strip():
            continue
        key = canonical_audio_key(path)
        if not key:
            continue
        # Prefer explicit corrected fields if present, else use target_reference.
        ref = (
            item.get("corrected_target_reference")
            or item.get("target_reference_corrected")
            or item.get("target_reference")
            or item.get("target_ref")
        )
        if not isinstance(ref, str):
            continue
        ref = ref.strip()
        if not ref:
            continue
        total += 1
        if key in corrected and corrected[key] != ref:
            conflicts += 1
        corrected[key] = ref
    stats = {"total_entries": total, "unique_targets": len(corrected), "conflicts": conflicts}
    return corrected, stats


def _resolve_input_paths(paths: Sequence[str]) -> List[Path]:
    out: List[Path] = []
    for p in paths:
        if not p:
            continue
        path = Path(p)
        if path.is_dir():
            candidate = path / "evaluation_per_sample_predictions_targetmix_sweep.json"
            if candidate.exists():
                out.append(candidate)
            else:
                print(f"[warn] No per-sample JSON found in dir: {path}")
            continue
        if path.exists():
            out.append(path)
        else:
            print(f"[warn] Missing input path: {path}")
    # de-dup
    seen = set()
    uniq: List[Path] = []
    for p in out:
        key = str(p.resolve()).lower()
        if key in seen:
            continue
        seen.add(key)
        uniq.append(p)
    return uniq


def apply_corrections_to_file(
    in_path: Path,
    corrected_map: Dict[str, str],
    *,
    inplace: bool,
    out_dir: Optional[Path],
    dry_run: bool,
) -> Dict[str, Any]:
    root = load_json_any(in_path)
    items, mode = _extract_items(root)
    if not items:
        return {"file": str(in_path), "updated": 0, "matched": 0, "mode": mode, "skipped": 0}

    updated = 0
    matched = 0
    for item in items:
        if item.get("__meta__"):
            continue
        path = item.get("target_audio_path") or item.get("target_path")
        if not isinstance(path, str) or not path.strip():
            continue
        key = canonical_audio_key(path)
        if key not in corrected_map:
            continue
        matched += 1
        new_ref = corrected_map[key]
        cur_ref = item.get("target_reference")
        if cur_ref != new_ref:
            updated += 1
            if not dry_run:
                item["target_reference"] = new_ref
                if "target_ref" in item:
                    item["target_ref"] = new_ref

    if dry_run:
        return {"file": str(in_path), "updated": updated, "matched": matched, "mode": mode, "skipped": 0}

    if out_dir is not None:
        out_path = out_dir / in_path.name
        write_json(out_path, root)
    elif inplace:
        backup = in_path.with_suffix(in_path.suffix + ".bak")
        if not backup.exists():
            backup.write_text(in_path.read_text(encoding="utf-8"), encoding="utf-8")
        write_json(in_path, root)

    return {"file": str(in_path), "updated": updated, "matched": matched, "mode": mode, "skipped": 0}


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--corrections_json", required=True)
    ap.add_argument("--in_jsons", nargs="+", required=True, help="Per-sample JSON files or directories.")
    ap.add_argument("--out_dir", default=None, help="Optional output directory (writes new files).")
    ap.add_argument("--inplace", action="store_true", default=True, help="Modify inputs in place (default).")
    ap.add_argument("--dry_run", action="store_true", help="Report counts without writing changes.")
    args = ap.parse_args()

    corrections_path = Path(args.corrections_json)
    if not corrections_path.exists():
        raise SystemExit(f"Missing corrections_json: {corrections_path}")

    corrections_root = load_json_any(corrections_path)
    corrected_map, stats = _extract_corrected_map(corrections_root)
    print(f"Corrections: {stats['unique_targets']} targets (conflicts={stats['conflicts']})")
    if not corrected_map:
        raise SystemExit("No corrected target references found in corrections_json.")

    in_paths = _resolve_input_paths(args.in_jsons)
    if not in_paths:
        raise SystemExit("No valid input JSONs to update.")

    out_dir = Path(args.out_dir) if args.out_dir else None
    if out_dir is not None:
        out_dir.mkdir(parents=True, exist_ok=True)

    total_updated = 0
    total_matched = 0
    for p in in_paths:
        res = apply_corrections_to_file(
            p,
            corrected_map,
            inplace=bool(args.inplace) and out_dir is None,
            out_dir=out_dir,
            dry_run=bool(args.dry_run),
        )
        total_updated += int(res.get("updated", 0))
        total_matched += int(res.get("matched", 0))
        print(f"{res['file']}: matched={res['matched']} updated={res['updated']}")

    print(f"Done. matched={total_matched} updated={total_updated}")


if __name__ == "__main__":
    main()

r"""stage_3_sort_audio_files_by_speaker_target_other.py

Sort audio files by whether they match a TARGET speaker, optionally using an OTHERS folder
as a negative reference cohort.

✅ Backwards compatible with downstream pipeline expectations:
- CSV first columns stay EXACTLY: file,score,decision,reason
- Extra columns are appended AFTER reason.

If you provide --other_ref_dir:
- score_target = cosine(target_centroid, emb)
- score_other_max = max cosine(other_ref_i, emb)
- compound score (written to CSV as "score") = score_target - score_other_max
- decision = TARGET if compound_score >= --threshold else OTHER

If you do NOT provide --other_ref_dir:
- score (CSV) = score_target
- decision = TARGET if score_target >= --threshold else OTHER

Typical threshold guidance:
- Without others: 0.50–0.75 (depends heavily on your data)
- With others (margin): often 0.00–0.20 (you must tune)

Usage (PowerShell)
------------------
I:\Whisper-training-env\Scripts\Activate.ps1

python "i:\whisper-acft\stage_3_sort_audio_files_by_speaker_target_other.py" 
  --in "I:\Record_chunks" 
  --target_ref_dir "I:\Record_only_by_harsha" 
  --other_ref_dir "I:\Record_others_compacted" 
  --target_out "I:\Record_chunks_sorted\target" 
  --other_out "I:\Record_chunks_sorted\other" 
  --threshold 0.10 
  --device cuda 
  --dry_run 
  --progress print 
  --batch_size 1 `
  --workers 1

Then run again without --dry_run to actually move/copy.

Resume:
- State file default: speaker_sort_state.json
- CSV default: speaker_sort_scores.csv (written in the CURRENT working directory)

"""

from __future__ import annotations

import argparse
import csv
import hashlib
import json
import os
import random
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Callable, Dict, List, Optional, Tuple

import numpy as np
import soundfile as sf
import torch
from concurrent.futures import ThreadPoolExecutor, as_completed

try:
    import librosa

    HAS_LIBROSA = True
except ImportError:
    HAS_LIBROSA = False


AUDIO_EXTS = {".wav", ".m4a", ".mp3", ".aac", ".flac", ".ogg", ".opus", ".mka", ".mp4"}
MODEL_ID = "pyannote/wespeaker-voxceleb-resnet34-LM"


def beep() -> None:
    """Audible notification when done."""
    try:
        import winsound

        winsound.Beep(1000, 250)
        winsound.Beep(1400, 200)
    except Exception:
        # terminal bell fallback
        print("\a", end="", flush=True)


def _which(exe: str) -> Optional[str]:
    return shutil.which(exe)


def require_ffmpeg() -> None:
    if _which("ffmpeg") is None:
        raise SystemExit(
            "ffmpeg not found on PATH. Install ffmpeg and try again.\n"
            "Windows: winget install Gyan.FFmpeg  (or use choco/scoop)\n"
            "macOS: brew install ffmpeg\n"
            "Linux: sudo apt-get install ffmpeg"
        )


def ffmpeg_to_wav_16k_mono(src: Path, dst: Path) -> None:
    cmd = [
        "ffmpeg",
        "-hide_banner",
        "-loglevel",
        "error",
        "-nostdin",
        "-y",
        "-i",
        str(src),
        "-ac",
        "1",
        "-ar",
        "16000",
        "-vn",
        str(dst),
    ]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if p.returncode != 0:
        raise RuntimeError(f"ffmpeg failed for {src}:\n{p.stderr}")


DIRECT_LIBROSA_EXTS = {".wav", ".flac"}  # boring + reliable on Windows


def load_audio_direct(audio_path: Path) -> Optional[np.ndarray]:
    """
    Load audio directly using librosa ONLY for formats that SoundFile/libsndfile
    tends to handle cleanly.

    For MP3/M4A/etc we return None so we fall back to ffmpeg.
    """
    if (not HAS_LIBROSA) or (audio_path.suffix.lower() not in DIRECT_LIBROSA_EXTS):
        return None
    try:
        audio, _sr = librosa.load(str(audio_path), sr=16000, mono=True)
        if audio is None or len(audio) == 0:
            return None
        return np.asarray(audio, dtype=np.float32)
    except Exception:
        return None


def _tmp_wav_path(tmp_dir: Path, af: Path) -> Path:
    """Stable temp path without collisions (avoid built-in hash() + modulo)."""
    h = hashlib.sha1(str(af).encode("utf-8", "ignore")).hexdigest()[:16]
    return tmp_dir / f"in_{h}.wav"


def get_duration_fast(audio_path: Path) -> Optional[float]:
    """Get duration quickly using ffprobe."""
    try:
        cmd = [
            "ffprobe",
            "-v",
            "quiet",
            "-show_entries",
            "format=duration",
            "-of",
            "csv=p=0",
            str(audio_path),
        ]
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if result.returncode == 0 and result.stdout.strip():
            return float(result.stdout.strip())
    except Exception:
        pass
    return None


def iter_audio_files(in_path: Path) -> List[Path]:
    if in_path.is_file():
        return [in_path]
    return sorted([p for p in in_path.rglob("*") if p.is_file() and p.suffix.lower() in AUDIO_EXTS])


def expand_files_or_dirs(items: List[Path]) -> List[Path]:
    out: List[Path] = []
    for p in items:
        if p.is_dir():
            out.extend(iter_audio_files(p))
        else:
            out.append(p)
    # filter + dedupe
    seen = set()
    filtered: List[Path] = []
    for p in out:
        if not p.exists():
            continue
        if p.is_file() and p.suffix.lower() in AUDIO_EXTS:
            sp = str(p)
            if sp not in seen:
                seen.add(sp)
                filtered.append(p)
    return filtered


def l2_normalize(x: np.ndarray, eps: float = 1e-12) -> np.ndarray:
    denom = np.linalg.norm(x, axis=-1, keepdims=True)
    denom = np.maximum(denom, eps)
    return x / denom


def ensure_dir(p: Path) -> None:
    p.mkdir(parents=True, exist_ok=True)


def safe_move_or_copy(src: Path, dst: Path, do_move: bool) -> None:
    ensure_dir(dst.parent)
    if do_move:
        shutil.move(str(src), str(dst))
    else:
        shutil.copy2(str(src), str(dst))


def cosine_sim(a: np.ndarray, b: np.ndarray) -> float:
    return float(np.dot(a, b))  # assumes both l2-normalized


def load_state(path: Path) -> dict:
    """Best-effort state load. If corrupt, we can still resume from the CSV."""
    if not path.exists():
        return {}
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f) or {}
    except Exception as e:
        print(f"Warning: failed to load state file {path}: {e}. Will fall back to CSV resume.")
        # Optional: rename the corrupt file so we don't keep re-reading it.
        try:
            backup = path.with_suffix(path.suffix + ".corrupt")
            if not backup.exists():
                os.replace(path, backup)
        except Exception:
            pass
        return {}


def save_state(path: Path, state: dict) -> None:
    """Atomic write to reduce the chance of a corrupt JSON file on crash/kill."""
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8", newline="") as f:
        json.dump(state, f, indent=2, ensure_ascii=False)
        f.flush()
        try:
            os.fsync(f.fileno())
        except Exception:
            pass
    os.replace(tmp, path)


def _canon_path(p: str) -> str:
    """Normalise paths for reliable resume on Windows (case-insensitive + normalised)."""
    try:
        return os.path.normcase(os.path.abspath(os.path.normpath(p)))
    except Exception:
        return os.path.normcase(p)

def load_processed_files_from_csv(csv_path: Path):
    """Return a set of already-processed file paths from the output CSV."""
    processed = set()
    if not csv_path.exists():
        return processed
    try:
        with csv_path.open("r", encoding="utf-8", newline="") as f:
            # Peek at the first line to decide DictReader vs raw reader
            first_line = f.readline()
            f.seek(0)
            if "file" in first_line.lower():
                reader = csv.DictReader(f)
                for row in reader:
                    fp = (row.get("file") or "").strip()
                    if fp:
                        processed.add(_canon_path(fp))
            else:
                reader = csv.reader(f)
                for row in reader:
                    if not row:
                        continue
                    fp = str(row[0]).strip()
                    if fp and fp.lower() != "file":
                        processed.add(_canon_path(fp))
    except Exception as e:
        print(f"Warning: failed reading CSV for resume {csv_path}: {e}")
    return processed


def compute_signature(payload: Dict[str, object]) -> str:
    blob = json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(blob).hexdigest()


def ensure_csv_header(csv_path: Path, fieldnames: List[str]) -> None:
    """If csv exists with different header, rewrite it with new header, padding missing fields."""
    if not csv_path.exists():
        return
    try:
        with csv_path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.reader(f)
            existing_header = next(reader, None)
        if not existing_header:
            return
        if existing_header == fieldnames:
            return

        # Rewrite
        tmp_path = csv_path.with_suffix(csv_path.suffix + ".tmp")
        with csv_path.open("r", encoding="utf-8", newline="") as fin, tmp_path.open(
            "w", encoding="utf-8", newline=""
        ) as fout:
            old_reader = csv.DictReader(fin)
            new_writer = csv.DictWriter(fout, fieldnames=fieldnames, extrasaction="ignore")
            new_writer.writeheader()
            for row in old_reader:
                out_row = {k: "" for k in fieldnames}
                for k, v in row.items():
                    if k in out_row and v is not None:
                        out_row[k] = v
                new_writer.writerow(out_row)

        tmp_path.replace(csv_path)
        print(f"Rewrote CSV header to include new columns: {csv_path}", flush=True)

    except Exception as e:
        print(f"Warning: Could not ensure CSV header for {csv_path}: {e}", flush=True)


def append_csv_row(csv_path: Path, fieldnames: List[str], row: Dict[str, str]) -> None:
    file_exists = csv_path.exists()
    try:
        with open(csv_path, "a", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
            if not file_exists:
                writer.writeheader()
            out_row = {k: "" for k in fieldnames}
            for k, v in row.items():
                if k in out_row:
                    out_row[k] = v
            writer.writerow(out_row)
    except Exception as e:
        print(f"Warning: Could not append to CSV {csv_path}: {e}", flush=True)


def make_progress(progress_mode: str, total: int) -> Callable[[int, str], None]:
    progress_mode = progress_mode.lower()
    if progress_mode == "none":
        return lambda i, msg: None

    if progress_mode == "print":
        def upd(i: int, msg: str) -> None:
            print(f"[{i}/{total}] {msg}", flush=True)
        return upd

    use_tqdm = progress_mode == "tqdm" or (progress_mode == "auto" and sys.stderr.isatty())
    if not use_tqdm:
        def upd(i: int, msg: str) -> None:
            print(f"[{i}/{total}] {msg}", flush=True)
        return upd

    try:
        from tqdm import tqdm
    except Exception:
        def upd(i: int, msg: str) -> None:
            print(f"[{i}/{total}] {msg}", flush=True)
        return upd

    bar = tqdm(total=total, desc="Scoring", unit="file", dynamic_ncols=True, file=sys.stderr)
    last_i = 0

    def upd(i: int, msg: str) -> None:
        nonlocal last_i
        step = max(0, i - last_i)
        if step:
            bar.update(step)
            last_i = i
        bar.set_postfix_str(msg[:120])

    return upd


def process_audio_batch(audio_files: List[Path], tmp_dir: Path, workers: int = 4) -> List[Tuple[Path, Optional[np.ndarray], Optional[str]]]:
    """Convert/load audio files in parallel, preserving input order."""

    def convert_file(af: Path) -> Tuple[Path, Optional[np.ndarray], Optional[str]]:
        audio = load_audio_direct(af)
        if audio is not None:
            return af, audio, None
        wav_path = _tmp_wav_path(tmp_dir, af)
        try:
            ffmpeg_to_wav_16k_mono(af, wav_path)
            audio, _ = sf.read(str(wav_path), dtype="float32")
            try:
                wav_path.unlink(missing_ok=True)
            except Exception:
                pass
            return af, audio, None
        except Exception as e:
            return af, None, str(e)

    results: List[Tuple[Path, Optional[np.ndarray], Optional[str]]] = [
        (p, None, "not_started") for p in audio_files
    ]

    max_workers = max(1, int(workers))
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_idx = {executor.submit(convert_file, af): i for i, af in enumerate(audio_files)}
        for fut in as_completed(future_to_idx):
            i = future_to_idx[fut]
            try:
                results[i] = fut.result()
            except Exception as e:
                results[i] = (audio_files[i], None, str(e))

    return results


def compute_batch_embeddings(
    audio_arrays: List[np.ndarray],
    inference,
    device: torch.device,
    batch_size: int = 32,
    min_batch_size: int = 1,
) -> Tuple[List[Optional[np.ndarray]], List[str]]:
    """Compute embeddings for audio arrays, with OOM backoff."""
    if not audio_arrays:
        return [], []

    tensors: List[torch.Tensor] = []
    for audio in audio_arrays:
        if audio is None:
            tensors.append(None)  # placeholder
            continue
        t = torch.from_numpy(np.asarray(audio)).float()
        if len(t.shape) == 1:
            t = t.unsqueeze(0)
        tensors.append(t)

    # Keep index mapping to preserve per-item results
    idx_map = [i for i, t in enumerate(tensors) if t is not None]
    valid_tensors = [tensors[i] for i in idx_map]
    if not valid_tensors:
        return [None] * len(audio_arrays), ["all_empty"]

    current_bs = min(int(batch_size), len(valid_tensors))
    current_bs = max(int(min_batch_size), current_bs)

    out_embeddings: List[Optional[np.ndarray]] = [None] * len(audio_arrays)
    errors: List[str] = []

    while current_bs >= int(min_batch_size):
        try:
            with torch.no_grad():
                for start in range(0, len(valid_tensors), current_bs):
                    sub = valid_tensors[start : start + current_bs]
                    max_len = max(t.shape[-1] for t in sub)
                    padded = []
                    for t in sub:
                        if t.shape[-1] < max_len:
                            pad = torch.zeros(1, max_len - t.shape[-1])
                            t = torch.cat([t, pad], dim=-1)
                        padded.append(t)

                    batch = torch.stack(padded).to(device)
                    emb = inference.model(batch)
                    if len(emb.shape) == 3:
                        emb = emb.mean(dim=1)
                    emb_np = emb.detach().cpu().numpy()

                    for j, e in enumerate(emb_np):
                        orig_idx = idx_map[start + j]
                        out_embeddings[orig_idx] = e

            return out_embeddings, []

        except torch.cuda.OutOfMemoryError:
            current_bs = current_bs // 2
            if current_bs < int(min_batch_size):
                errors.append("OOM: could not process even at min batch size")
                break
            print(f"OOM detected, reducing batch size to {current_bs}...", flush=True)
            torch.cuda.empty_cache()
        except Exception as e:
            errors.append(f"Error computing embeddings: {e}")
            break

    return out_embeddings, errors


def build_ref_embeddings(
    ref_paths: List[Path],
    tmp_dir: Path,
    inference,
    device: torch.device,
    workers: int,
    batch_size: int,
    min_batch_size: int,
    label: str,
    progress_mode: str = "print",
) -> Tuple[List[Path], np.ndarray]:
    """Return (paths_used, embeddings_matrix[N,D]) with L2-normalised embeddings."""
    if not ref_paths:
        return [], np.zeros((0, 1), dtype=np.float32)

    print(f"Loading {len(ref_paths)} {label} reference file(s) for embedding...", flush=True)

    conv = process_audio_batch(ref_paths, tmp_dir, workers=workers)
    good_paths: List[Path] = []
    audios: List[np.ndarray] = []

    for p, audio, err in conv:
        if err is None and audio is not None:
            good_paths.append(p)
            audios.append(audio)
        else:
            print(f"[ref:{label}] skip {p.name}: {err}", flush=True)

    if not audios:
        raise ValueError(f"No valid {label} reference audio could be loaded.")

    # embeddings per ref (aligned to good_paths)
    emb_list, emb_errors = compute_batch_embeddings(
        audios, inference, device, batch_size=batch_size, min_batch_size=min_batch_size
    )

    if emb_errors:
        raise RuntimeError(f"Failed computing {label} reference embeddings: {emb_errors}")

    embs: List[np.ndarray] = []
    used_paths: List[Path] = []

    for p, e in zip(good_paths, emb_list):
        if e is None:
            continue
        e2 = l2_normalize(np.asarray(e).reshape(1, -1))[0].astype(np.float32)
        embs.append(e2)
        used_paths.append(p)

    if not embs:
        raise ValueError(f"No usable {label} reference embeddings computed.")

    mat = np.stack(embs, axis=0)
    return used_paths, mat


def sample_paths(paths: List[Path], mode: str, max_n: int, seed: int) -> List[Path]:
    if max_n <= 0 or len(paths) <= max_n:
        return paths
    if mode == "random":
        rng = random.Random(int(seed))
        idx = list(range(len(paths)))
        rng.shuffle(idx)
        return [paths[i] for i in idx[:max_n]]
    # default: first
    return paths[:max_n]


def main() -> None:
    require_ffmpeg()

    ap = argparse.ArgumentParser(description="Sort audio files by whether they match a target speaker (with optional others cohort).")
    ap.add_argument("--in", dest="in_path", required=True, help="Input file or directory containing many audio files")

    # Target refs
    ap.add_argument("--target_ref_dir", default=None, help="Directory of TARGET speaker reference audio files (preferred)")
    ap.add_argument("--ref", dest="ref_files", nargs="*", default=None, help="Legacy: TARGET reference audio files or directories")

    # Others cohort
    ap.add_argument("--other_ref_dir", default=None, help="Directory of OTHER speakers reference audio files (optional)")
    ap.add_argument("--other_ref_max", type=int, default=200, help="Max number of OTHER reference files to use (0=all)")
    ap.add_argument("--other_ref_sample", choices=["first", "random"], default="first", help="How to choose other refs if capped")
    ap.add_argument("--seed", type=int, default=1337, help="Seed for random sampling")

    ap.add_argument("--target_out", required=True, help="Directory to put files matching target speaker")
    ap.add_argument("--other_out", required=True, help="Directory to put all other files")

    ap.add_argument("--threshold", type=float, default=0.5, help="Threshold for TARGET decision. If --other_ref_dir is set, this is a margin threshold.")
    ap.add_argument("--min_seconds", type=float, default=2.0, help="Route to OTHER files shorter than this")
    ap.add_argument("--device", choices=["cpu", "cuda"], default="cpu", help="Use cuda if you have a GPU")
    ap.add_argument("--move", action="store_true", help="Move files instead of copying")
    ap.add_argument("--copy", action="store_true", help="Copy files (default if neither --move nor --copy set)")
    ap.add_argument("--dry_run", action="store_true", help="Do not move/copy; just print decisions and write CSV")
    ap.add_argument("--progress", choices=["auto", "tqdm", "print", "none"], default="auto", help="Progress display mode")
    ap.add_argument("--log_every", type=int, default=0, help="Also print a line every N files (0=off)")
    ap.add_argument("--hf_token", default=os.environ.get("HF_TOKEN", ""), help="Optional Hugging Face token")

    ap.add_argument("--batch_size", type=int, default=16, help="Initial batch size for embedding (auto-reduced on OOM)")
    ap.add_argument("--min_batch_size", type=int, default=1, help="Minimum batch size to attempt")
    ap.add_argument("--workers", type=int, default=8, help="Number of worker threads for audio conversion")

    ap.add_argument("--state_file", default="speaker_sort_state.json", help="State file for resuming")
    ap.add_argument("--no_resume", action="store_true", help="Force restart from beginning")
    ap.add_argument("--force_resume_mismatch", action="store_true", help="Allow resume even if refs/params changed (not recommended)")

    args = ap.parse_args()

    in_path = Path(args.in_path)
    target_out = Path(args.target_out)
    other_out = Path(args.other_out)

    do_move = bool(args.move)
    if args.copy:
        do_move = False

    if not in_path.exists():
        raise SystemExit(f"Input path not found: {in_path}")

    # Build target refs from folder OR legacy list
    target_refs: List[Path] = []
    if args.target_ref_dir:
        td = Path(args.target_ref_dir)
        if not td.exists():
            raise SystemExit(f"target_ref_dir not found: {td}")
        target_refs = iter_audio_files(td)
    else:
        legacy = [Path(p) for p in (args.ref_files or [])]
        if legacy:
            target_refs = expand_files_or_dirs(legacy)

    if not target_refs:
        raise SystemExit("No TARGET reference files found. Provide --target_ref_dir or --ref ...")

    # Build other refs
    other_refs: List[Path] = []
    if args.other_ref_dir:
        od = Path(args.other_ref_dir)
        if not od.exists():
            raise SystemExit(f"other_ref_dir not found: {od}")
        other_refs = iter_audio_files(od)
        other_refs = sample_paths(other_refs, args.other_ref_sample, int(args.other_ref_max), int(args.seed))

    audio_files = iter_audio_files(in_path)
    if not audio_files:
        raise SystemExit(f"No audio files found under: {in_path}")

    # State + CSV
    state_file = Path(args.state_file)
    csv_path = Path.cwd() / "speaker_sort_scores.csv"

    # Fieldnames (keep first 4 stable)
    base_fields = ["file", "score", "decision", "reason"]
    extra_fields = [
        "score_target",
        "score_other_max",
        "other_top1_ref",
        "compound_mode",
    ]
    use_compound = bool(other_refs)
    fieldnames = base_fields + (extra_fields if use_compound else [])

    ensure_csv_header(csv_path, fieldnames)

    no_resume = getattr(args, "no_resume", False)
    existing_state = load_state(state_file) if not no_resume else {}
    processed_files = {_canon_path(p) for p in existing_state.get("processed_files", [])}

    # CSV is a durable source of truth: use it to recover progress if state.json is corrupt/missing
    processed_from_csv = load_processed_files_from_csv(csv_path) if not no_resume else set()
    if processed_from_csv:
        print(f"Resume: found {len(processed_from_csv)} processed file(s) in CSV -> skipping them.")
        processed_files |= processed_from_csv

    # Signature to prevent mixing runs
    sig_payload = {
        "model_id": MODEL_ID,
        "use_compound": use_compound,
        "threshold": float(args.threshold),
        "min_seconds": float(args.min_seconds),
        "target_refs": [str(p) for p in target_refs],
        "other_refs": [str(p) for p in other_refs],
        "other_ref_max": int(args.other_ref_max),
        "other_ref_sample": str(args.other_ref_sample),
    }
    run_sig = compute_signature(sig_payload)

    old_sig = existing_state.get("run_signature")
    if processed_files and not args.no_resume and old_sig and old_sig != run_sig and not args.force_resume_mismatch:
        raise SystemExit(
            "State file exists but refs/params changed.\n"
            "Run with --no_resume to restart, or --force_resume_mismatch (not recommended).\n"
            f"state_file: {state_file}"
        )

    remaining_files = [f for f in audio_files if _canon_path(str(f)) not in processed_files]
    if not remaining_files:
        print("All files have already been processed!", flush=True)
        return

    print(f"Found {len(audio_files)} total audio file(s).", flush=True)
    print(f"Processing {len(remaining_files)} remaining file(s).", flush=True)

    # Lazy import
    print("Loading speaker embedding model... (first run may download weights)", flush=True)
    from pyannote.audio import Model, Inference

    device = torch.device(args.device)
    model = Model.from_pretrained(MODEL_ID, token=args.hf_token or None)
    inference = Inference(model, window="whole")
    inference.to(device)

    ensure_dir(target_out)
    ensure_dir(other_out)

    progress_upd = make_progress(args.progress, total=len(remaining_files))

    # Track state
    current_processed_files = sorted(processed_files)

    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td)

        # TARGET centroid
        used_target_paths, target_embs = build_ref_embeddings(
            target_refs,
            tmp,
            inference,
            device,
            workers=int(args.workers),
            batch_size=int(args.batch_size),
            min_batch_size=int(args.min_batch_size),
            label="TARGET",
        )
        target_centroid = l2_normalize(np.mean(target_embs, axis=0, keepdims=True))[0]

        # OTHERS embeddings matrix
        other_mat = None
        other_paths_used: List[Path] = []
        if use_compound:
            other_paths_used, other_mat0 = build_ref_embeddings(
                other_refs,
                tmp,
                inference,
                device,
                workers=int(args.workers),
                batch_size=int(args.batch_size),
                min_batch_size=int(args.min_batch_size),
                label="OTHERS",
            )
            other_mat = other_mat0  # shape (N,D)
            print(f"Using {other_mat.shape[0]} OTHER reference embeddings (max-sim cohort).", flush=True)
        else:
            print("No --other_ref_dir set (or empty). Using TARGET-only scoring.", flush=True)

        # Process files in batches (conversion parallel, embedding batched)
        bs = int(args.batch_size)
        total = len(remaining_files)
        total_batches = (total + bs - 1) // bs

        for batch_idx in range(total_batches):
            start = batch_idx * bs
            end = min(start + bs, total)
            batch_files = remaining_files[start:end]

            # Pre-filter short files
            to_process: List[Path] = []
            for af in batch_files:
                dur = get_duration_fast(af)
                if dur is not None and dur < float(args.min_seconds):
                    row = {
                        "file": str(af),
                        "score": "",
                        "decision": "OTHER",
                        "reason": f"too_short({dur:.2f}s)",
                    }
                    if use_compound:
                        row.update(
                            {
                                "score_target": "",
                                "score_other_max": "",
                                "other_top1_ref": "",
                                "compound_mode": "target_minus_othermax",
                            }
                        )
                    append_csv_row(csv_path, fieldnames, row)
                    current_processed_files.append(_canon_path(str(af)))
                    progress_upd(start + batch_files.index(af) + 1, af.name)
                else:
                    to_process.append(af)

            if not to_process:
                save_state(state_file, {"processed_files": current_processed_files, "run_signature": run_sig})
                continue

            conv = process_audio_batch(to_process, tmp, workers=int(args.workers))

            good_files: List[Path] = []
            audios: List[np.ndarray] = []
            for af, audio, err in conv:
                if err is not None or audio is None:
                    row = {
                        "file": str(af),
                        "score": "",
                        "decision": "ERROR_CONVERT",
                        "reason": (err or "convert_failed"),
                    }
                    if use_compound:
                        row.update(
                            {
                                "score_target": "",
                                "score_other_max": "",
                                "other_top1_ref": "",
                                "compound_mode": "target_minus_othermax",
                            }
                        )
                    append_csv_row(csv_path, fieldnames, row)
                    current_processed_files.append(_canon_path(str(af)))
                    progress_upd(start + batch_files.index(af) + 1, af.name)
                else:
                    good_files.append(af)
                    audios.append(audio)

            if not audios:
                save_state(state_file, {"processed_files": current_processed_files, "run_signature": run_sig})
                continue

            emb_list, emb_errors = compute_batch_embeddings(
                audios,
                inference,
                device,
                batch_size=int(args.batch_size),
                min_batch_size=int(args.min_batch_size),
            )

            if emb_errors:
                # mark all as embedding error
                for af in good_files:
                    row = {
                        "file": str(af),
                        "score": "",
                        "decision": "ERROR_EMBEDDING",
                        "reason": ";".join(emb_errors)[:500],
                    }
                    if use_compound:
                        row.update(
                            {
                                "score_target": "",
                                "score_other_max": "",
                                "other_top1_ref": "",
                                "compound_mode": "target_minus_othermax",
                            }
                        )
                    append_csv_row(csv_path, fieldnames, row)
                    current_processed_files.append(_canon_path(str(af)))
                    progress_upd(start + batch_files.index(af) + 1, af.name)

                save_state(state_file, {"processed_files": current_processed_files, "run_signature": run_sig})
                continue

            for af, e in zip(good_files, emb_list):
                if e is None:
                    continue

                emb = l2_normalize(np.asarray(e).reshape(1, -1))[0]

                s_target = cosine_sim(target_centroid, emb)

                if use_compound and other_mat is not None and other_mat.shape[0] > 0:
                    sims = other_mat @ emb  # (N,)
                    j = int(np.argmax(sims))
                    s_other = float(sims[j])
                    other_top = str(other_paths_used[j]) if j < len(other_paths_used) else ""
                    compound = float(s_target - s_other)
                    score_for_decision = compound
                    score_str = f"{compound:.6f}"
                    decision = "TARGET" if compound >= float(args.threshold) else "OTHER"
                    row = {
                        "file": str(af),
                        "score": score_str,
                        "decision": decision,
                        "reason": "",
                        "score_target": f"{s_target:.6f}",
                        "score_other_max": f"{s_other:.6f}",
                        "other_top1_ref": other_top,
                        "compound_mode": "target_minus_othermax",
                    }
                else:
                    score_for_decision = s_target
                    score_str = f"{s_target:.6f}"
                    decision = "TARGET" if s_target >= float(args.threshold) else "OTHER"
                    row = {
                        "file": str(af),
                        "score": score_str,
                        "decision": decision,
                        "reason": "",
                    }

                append_csv_row(csv_path, fieldnames, row)
                current_processed_files.append(_canon_path(str(af)))

                # progress
                file_idx = start + batch_files.index(af) + 1
                progress_upd(file_idx, af.name)

                if args.log_every and file_idx % int(args.log_every) == 0:
                    if use_compound:
                        print(
                            f"[{file_idx}/{len(remaining_files)}] {af.name} -> {decision} score={score_str} (target={row.get('score_target','')}, other={row.get('score_other_max','')})",
                            flush=True,
                        )
                    else:
                        print(
                            f"[{file_idx}/{len(remaining_files)}] {af.name} -> {decision} score={score_str}",
                            flush=True,
                        )

                # move/copy
                if not args.dry_run:
                    rel = af.relative_to(in_path) if in_path.is_dir() else Path(af.name)
                    dst = (target_out / rel) if decision == "TARGET" else (other_out / rel)
                    safe_move_or_copy(af, dst, do_move=do_move)

            save_state(state_file, {"processed_files": current_processed_files, "run_signature": run_sig})

    print("\nDone.", flush=True)
    print(f"CSV log: {csv_path}", flush=True)
    print(f"State file: {state_file}", flush=True)
    if args.dry_run:
        print("Dry-run only: no files moved/copied.", flush=True)
    else:
        print("Files have been sorted.", flush=True)

    beep()


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        raise SystemExit(130)

#!/usr/bin/env python3
"""Stage 5: Convert number words to digits in manifest raw_transcription.

Examples:
  "twenty one" -> "21"
  "five three two one" -> "5321"
  "twenty-one" -> "21"
  "five, three, two, one" -> "5321"
"""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Dict, Iterable, List, Optional

from tqdm import tqdm


_UNITS: Dict[str, int] = {
    "zero": 0,
    "oh": 0,
    "one": 1,
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
}

_TEENS: Dict[str, int] = {
    "ten": 10,
    "eleven": 11,
    "twelve": 12,
    "thirteen": 13,
    "fourteen": 14,
    "fifteen": 15,
    "sixteen": 16,
    "seventeen": 17,
    "eighteen": 18,
    "nineteen": 19,
}

_TENS: Dict[str, int] = {
    "twenty": 20,
    "thirty": 30,
    "forty": 40,
    "fifty": 50,
    "sixty": 60,
    "seventy": 70,
    "eighty": 80,
    "ninety": 90,
}

_SCALES: Dict[str, int] = {
    "hundred": 100,
    "thousand": 1_000,
    "million": 1_000_000,
    "billion": 1_000_000_000,
}

_NUM_WORDS = set(_UNITS) | set(_TEENS) | set(_TENS) | set(_SCALES) | {"and"}
_NUM_START_WORDS = _NUM_WORDS - {"and"}
_DIGIT_WORDS = set(_UNITS)

_NUM_PATTERN = re.compile(
    r"\b(?:"
    + "|".join(sorted(_NUM_START_WORDS, key=len, reverse=True))
    + r")\b(?:[\s,-]+\b(?:"
    + "|".join(sorted(_NUM_WORDS, key=len, reverse=True))
    + r")\b)*",
    re.IGNORECASE,
)


def _words_to_number(words: List[str]) -> Optional[int]:
    total = 0
    current = 0
    for w in words:
        if w == "and":
            continue
        if w in _UNITS:
            current += _UNITS[w]
        elif w in _TEENS:
            current += _TEENS[w]
        elif w in _TENS:
            current += _TENS[w]
        elif w in _SCALES:
            scale = _SCALES[w]
            if current == 0:
                current = 1
            if scale == 100:
                current *= scale
            else:
                total += current * scale
                current = 0
        else:
            return None
    return total + current


def _replace_match(match: re.Match) -> str:
    chunk = match.group(0)
    words = re.findall(r"[A-Za-z']+", chunk.lower())
    if not words:
        return chunk

    cleaned = [w for w in words if w in _NUM_WORDS]
    if not cleaned:
        return chunk

    if all(w in _DIGIT_WORDS for w in cleaned):
        return "".join(str(_UNITS[w]) for w in cleaned)

    num = _words_to_number(cleaned)
    if num is None:
        return chunk
    return str(num)


def normalize_number_words(text: str) -> str:
    return _NUM_PATTERN.sub(_replace_match, text)


def process_manifest(input_path: Path, output_path: Path, field: str) -> tuple[int, int]:
    total = 0
    changed = 0
    total_lines = sum(1 for _ in input_path.open("r", encoding="utf-8"))

    with input_path.open("r", encoding="utf-8") as infile, output_path.open("w", encoding="utf-8") as outfile:
        for line in tqdm(infile, total=total_lines, desc="Converting numbers"):
            if not line.strip():
                continue
            obj = json.loads(line)
            total += 1
            txt = obj.get(field, "")
            if isinstance(txt, str) and txt:
                new_txt = normalize_number_words(txt)
                if new_txt != txt:
                    obj[field] = new_txt
                    changed += 1
            outfile.write(json.dumps(obj, ensure_ascii=False) + "\n")

    return total, changed


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="Convert number words to digits in manifest text.")
    p.add_argument("--input", required=True, type=Path, help="Input JSONL manifest.")
    p.add_argument("--output", required=True, type=Path, help="Output JSONL manifest.")
    p.add_argument("--field", default="raw_transcription", help="Field to normalize (default: raw_transcription).")
    return p.parse_args()


def main() -> None:
    args = parse_args()
    if not args.input.exists():
        raise FileNotFoundError(f"Input file not found: {args.input}")
    args.output.parent.mkdir(parents=True, exist_ok=True)

    total, changed = process_manifest(args.input, args.output, args.field)
    print(f"Completed. Lines: {total}, changed: {changed}. Output: {args.output}")
    try:
        import winsound  # type: ignore

        winsound.Beep(880, 400)
    except Exception:
        print("\a")


if __name__ == "__main__":
    main()

param(
    [string]$PlanCsv = "i:\\whisper-acft\\run_folder_rename_plan.csv",
    [switch]$Apply
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Ensure-Junction([string]$LinkPath, [string]$TargetPath) {
    if (Test-Path -LiteralPath $LinkPath) {
        $item = Get-Item -LiteralPath $LinkPath -Force
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
            return
        }
        throw "Cannot create junction. Path already exists and is not a junction: $LinkPath"
    }
    cmd /c mklink /J "$LinkPath" "$TargetPath" | Out-Null
}

function Write-RenameNote(
    [string]$FolderPath,
    [pscustomobject]$Row,
    [string]$OldPath,
    [string]$NewPath
) {
    $notePath = Join-Path $FolderPath "RENAMED_FOLDER_NOTE.md"
    $ts = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
    $content = @"
# Folder Rename Note

- Timestamp: $ts
- Old path: $OldPath
- New path: $NewPath
- Original name: $($Row.original_name)
- Canonical name: $($Row.new_folder_name)

## Why this was renamed
$($Row.reason)

## Evidence used
$($Row.evidence)

## Canonical tags
- kind: $($Row.kind)
- stage: $($Row.stage)
- base: $($Row.base)
- method: $($Row.method)
- adapter: $($Row.adapter)
- quant: $($Row.quant)
- ctx: $($Row.ctx)
- rows: $($Row.rows)
- run_id: $($Row.run_id)

## Backward compatibility
The old folder name is preserved as a junction alias to this folder.
"@
    Set-Content -Path $notePath -Value $content -Encoding UTF8
}

if (-not (Test-Path -LiteralPath $PlanCsv)) {
    throw "Plan file not found: $PlanCsv"
}

$plan = Import-Csv -Path $PlanCsv
if (-not $plan -or $plan.Count -eq 0) {
    throw "Plan is empty: $PlanCsv"
}

$result = New-Object System.Collections.Generic.List[object]

foreach ($row in $plan) {
    $oldPath = $row.original_path
    $parent = Split-Path -Path $oldPath -Parent
    $newPath = Join-Path $parent $row.new_folder_name
    $status = "dry_run"
    $details = ""

    try {
        $oldExists = Test-Path -LiteralPath $oldPath
        $newExists = Test-Path -LiteralPath $newPath

        if (-not $Apply) {
            if (-not $oldExists -and -not $newExists) {
                $status = "missing_both"
                $details = "old/new paths both missing"
            } elseif ($oldExists -and $newExists) {
                $status = "conflict"
                $details = "old and new both exist"
            } elseif (-not $oldExists -and $newExists) {
                $status = "already_renamed"
                $details = "new exists; old missing"
            } else {
                $status = "ready"
                $details = "rename + junction + note will be applied"
            }
        } else {
            if ($oldExists -and -not $newExists) {
                Rename-Item -LiteralPath $oldPath -NewName $row.new_folder_name
                $status = "renamed"
                $details = "folder renamed"
            } elseif (-not $oldExists -and $newExists) {
                $status = "already_renamed"
                $details = "new exists; old missing"
            } elseif ($oldExists -and $newExists) {
                $oldItem = Get-Item -LiteralPath $oldPath -Force
                if ($oldItem.Attributes -band [IO.FileAttributes]::ReparsePoint) {
                    $status = "already_renamed"
                    $details = "new exists and old is junction alias"
                } else {
                    $status = "conflict"
                    $details = "old and new both exist"
                }
            } else {
                $status = "missing_both"
                $details = "old/new paths both missing"
            }

            if ($status -in @("renamed", "already_renamed")) {
                Ensure-Junction -LinkPath $oldPath -TargetPath $newPath
                if (Test-Path -LiteralPath $newPath) {
                    Write-RenameNote -FolderPath $newPath -Row $row -OldPath $oldPath -NewPath $newPath
                }
            }
        }
    } catch {
        $status = "error"
        $details = $_.Exception.Message
    }

    $result.Add([pscustomobject]@{
        original_path = $oldPath
        new_path = $newPath
        status = $status
        details = $details
    })
}

$out = [System.IO.Path]::ChangeExtension($PlanCsv, ".apply_result.csv")
$result | Export-Csv -Path $out -NoTypeInformation -Encoding UTF8
Write-Host "Result written:" $out
$result | Group-Object status | Sort-Object Name | ForEach-Object { Write-Host ("{0}: {1}" -f $_.Name, $_.Count) }

param(
    [string]$Root = "I:\\",
    [string]$OutCsv = "i:\\whisper-acft\\run_folder_rename_plan.csv",
    [string[]]$Paths = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Normalize-Token([string]$value) {
    if ([string]::IsNullOrWhiteSpace($value)) { return "unk" }
    $v = $value.ToLowerInvariant()
    $v = $v -replace "[^a-z0-9]+", "-"
    $v = $v -replace "-{2,}", "-"
    $v = $v.Trim("-")
    if ([string]::IsNullOrWhiteSpace($v)) { return "unk" }
    return $v
}

function First-Hit([string]$path, [string]$pattern) {
    $m = Select-String -Path $path -Pattern $pattern -CaseSensitive:$false -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($m) { return ($m.Line -replace "\s+", " ").Trim() }
    return ""
}

function Parse-Base([string]$line, [string]$name) {
    $s = "$line $name".ToLowerInvariant()
    if ($s -match "futo-org/acft-whisper-small\.en|futo[_-].*small[_-]en|small[_-]en") { return "futo-small-en" }
    if ($s -match "futo-org/acft-whisper-tiny\.en|futo[_-].*tiny[_-]en") { return "futo-tiny-en" }
    if ($s -match "openai/whisper-small\.en|openai[_-].*small[_-]en") { return "openai-small-en" }
    if ($s -match "openai/whisper-tiny\.en|openai[_-].*tiny[_-]en|tiny[_-]en") { return "openai-tiny-en" }
    return "unk"
}

function Parse-Stage([string]$name) {
    if ($name -match "^stage[_-](\d+[a-z]?)") { return $matches[1].ToLowerInvariant() }
    if ($name -match "^dynamic_n_ctx") { return "legacy" }
    if ($name -match "^checkpoints_") { return "legacy" }
    return "unk"
}

function Parse-Method([string]$script, [string]$name, [string]$kind) {
    $s = "$script $name".ToLowerInvariant()
    if ($kind -eq "eval_only") { return "eval-only" }
    if ($s -match "stage_17.*qat_dora") { return "s17-qat-dora" }
    if ($s -match "stage_17.*qat_lora") { return "s17-qat-lora" }
    if ($s -match "stage_17.*_qat\.py") { return "s17-qat-full" }
    if ($s -match "stage_17.*version_only\.py") { return "s17-full" }
    if ($s -match "stage_18_wer_training") { return "s18-full" }
    return "unk"
}

function Parse-Adapter([string]$rLine, [string]$aLine, [string]$doraLine, [string]$script, [int]$adapterFiles, [int]$fullFiles) {
    $r = ""
    $a = ""
    if ($rLine -match "r\s*=\s*(\d+)") { $r = $matches[1] }
    if ($aLine -match "lora_alpha\s*=\s*(\d+)") { $a = $matches[1] }
    $useDora = ($doraLine -match "true")
    $s = $script.ToLowerInvariant()

    if ($useDora -or $s -match "qat_dora") {
        if (-not $r) { $r = "unk" }
        if (-not $a) { $a = "unk" }
        return "dora-r$r-a$a"
    }
    if ($s -match "qat_lora") { return "lora" }
    if ($adapterFiles -gt 0 -and $fullFiles -eq 0) { return "lora" }
    if ($fullFiles -gt 0 -and $adapterFiles -eq 0) { return "full" }
    if ($adapterFiles -gt 0 -and $fullFiles -gt 0) { return "mixed" }
    return "unk"
}

function Parse-Quant([string]$script) {
    $s = $script.ToLowerInvariant()
    if ($s -match "qat") { return "qat" }
    if ([string]::IsNullOrWhiteSpace($s)) { return "unk" }
    return "noqat"
}

function Parse-Ctx([string]$name, [bool]$sawNctx) {
    $n = $name.ToLowerInvariant()
    if ($n -match "dynamic_n_ctx") { return "dyn" }
    if ($n -match "_n_ctx_") { return "static" }
    if ($sawNctx) { return "dyn" }
    return "unk"
}

function Parse-Rows([string]$manifestLine) {
    if ($manifestLine -match "manifest rows:\s*(\d+)") { return $matches[1] }
    return "unk"
}

function Parse-Id([string]$name) {
    if ($name -match "(\d{8})") { return $matches[1] }
    if ($name -match "(\d+)$") { return $matches[1] }
    return "unk"
}

function Build-Name([hashtable]$meta) {
    $tokens = @(
        "RUN",
        ("k-{0}" -f (Normalize-Token $meta["kind"])),
        ("s-{0}" -f (Normalize-Token $meta["stage"])),
        ("b-{0}" -f (Normalize-Token $meta["base"])),
        ("m-{0}" -f (Normalize-Token $meta["method"])),
        ("a-{0}" -f (Normalize-Token $meta["adapter"])),
        ("q-{0}" -f (Normalize-Token $meta["quant"])),
        ("c-{0}" -f (Normalize-Token $meta["ctx"])),
        ("r-{0}" -f (Normalize-Token $meta["rows"])),
        ("id-{0}" -f (Normalize-Token $meta["id"]))
    )
    return ($tokens -join "__")
}

if (-not $Paths -or $Paths.Count -eq 0) {
    $candidates = New-Object System.Collections.Generic.List[string]
    foreach ($f in @("Stage_*", "Dynamic_n_ctx_*", "checkpoints_partialctx*")) {
        Get-ChildItem -Path $Root -Directory -Filter $f -ErrorAction SilentlyContinue | ForEach-Object {
            $candidates.Add($_.FullName)
        }
    }
    $Paths = $candidates | Sort-Object -Unique
}

$rows = New-Object System.Collections.Generic.List[object]
$usedNames = @{}

foreach ($path in $Paths) {
    if (-not (Test-Path -LiteralPath $path)) { continue }
    $item = Get-Item -LiteralPath $path -ErrorAction SilentlyContinue
    if (-not $item -or -not $item.PSIsContainer) { continue }

    $name = $item.Name
    $files = Get-ChildItem -LiteralPath $path -Recurse -File -Depth 4 -ErrorAction SilentlyContinue
    $dirs = Get-ChildItem -LiteralPath $path -Recurse -Directory -Depth 4 -ErrorAction SilentlyContinue
    $logs = Get-ChildItem -LiteralPath $path -Recurse -File -Filter "console.log" -ErrorAction SilentlyContinue

    $runState = @($files | Where-Object Name -eq "run_state.json").Count
    $modelEpoch = @($dirs | Where-Object Name -like "model_epoch_*").Count
    $adapterFiles = @($files | Where-Object Name -eq "adapter_model.safetensors").Count
    $fullFiles = @($files | Where-Object { $_.Name -eq "model.safetensors" -or $_.Name -eq "pytorch_model.bin" }).Count
    $eval = @($files | Where-Object Name -like "evaluation_results*.json").Count
    $pred = @($files | Where-Object Name -like "evaluation_per_sample_predictions*.json").Count

    $script = ""
    $manifest = ""
    $baseLine = ""
    $rLine = ""
    $aLine = ""
    $doraLine = ""
    $sawNctx = $false

    if (@($logs).Count -gt 0) {
        $log = $logs | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        $cmd = First-Hit $log.FullName "^Command:"
        if ($cmd -match "stage_[^\s]+\.py") { $script = $matches[0] }
        $manifest = First-Hit $log.FullName "Manifest rows:"
        $baseLine = First-Hit $log.FullName "--futo-model-id|Loading student from base:"
        $rLine = First-Hit $log.FullName "\[peft\] r="
        $aLine = First-Hit $log.FullName "\[peft\] lora_alpha="
        $doraLine = First-Hit $log.FullName "\[peft\] use_dora="
        $nctxLine = First-Hit $log.FullName "n_ctx="
        $sawNctx = -not [string]::IsNullOrWhiteSpace($nctxLine)
    }

    $kind = "misc"
    if (($eval -gt 0 -or $pred -gt 0) -and ($runState -gt 0 -or $modelEpoch -gt 0 -or $adapterFiles -gt 0 -or $fullFiles -gt 0)) {
        $kind = "train_eval"
    } elseif ($eval -gt 0 -or $pred -gt 0) {
        $kind = "eval_only"
    } elseif ($runState -gt 0 -or $modelEpoch -gt 0 -or $adapterFiles -gt 0 -or $fullFiles -gt 0) {
        $kind = "train_only"
    } elseif (@($logs).Count -gt 0) {
        $kind = "partial"
    }

    $stage = Parse-Stage $name
    $base = Parse-Base $baseLine $name
    $method = Parse-Method $script $name $kind
    $adapter = Parse-Adapter $rLine $aLine $doraLine $script $adapterFiles $fullFiles
    $quant = Parse-Quant $script
    $ctx = Parse-Ctx $name $sawNctx
    $rowsVal = Parse-Rows $manifest
    $id = Parse-Id $name

    $meta = @{
        kind = $kind; stage = $stage; base = $base; method = $method
        adapter = $adapter; quant = $quant; ctx = $ctx; rows = $rowsVal; id = $id
    }
    $newName = Build-Name $meta

    if ($usedNames.ContainsKey($newName)) {
        $usedNames[$newName]++
        $newName = "${newName}__u-$($usedNames[$newName])"
    } else {
        $usedNames[$newName] = 0
    }

    $reason = "renamed using artifact/log-based canonical nomenclature"
    $evidence = @()
    if ($script) { $evidence += "script=$script" }
    if ($manifest) { $evidence += ($manifest -replace "Manifest rows:\s*", "rows=") }
    if ($rLine) { $evidence += ($rLine -replace "^\[peft\]\s*", "") }
    if ($aLine) { $evidence += ($aLine -replace "^\[peft\]\s*", "") }
    if ($doraLine) { $evidence += ($doraLine -replace "^\[peft\]\s*", "") }
    if ($baseLine) { $evidence += "base_hint=$baseLine" }

    $rows.Add([pscustomobject]@{
        original_path = $path
        original_name = $name
        new_folder_name = $newName
        kind = $kind
        stage = $stage
        base = $base
        method = $method
        adapter = $adapter
        quant = $quant
        ctx = $ctx
        rows = $rowsVal
        run_id = $id
        reason = $reason
        evidence = ($evidence -join " | ")
    })
}

$rows | Sort-Object original_path | Export-Csv -Path $OutCsv -NoTypeInformation -Encoding UTF8
Write-Host "Plan written:" $OutCsv
Write-Host "Rows:" $rows.Count

#!/usr/bin/env python3
from __future__ import annotations

import argparse
import csv
import hashlib
import json
import os
import sys
import shutil
import math
from datetime import datetime, timezone
from pathlib import Path, PureWindowsPath
from typing import Any

SCRIPT_DIR = Path(__file__).resolve().parent
REPO_ROOT = SCRIPT_DIR.parent
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from cloud_eval_common import parse_env_file, resolve_hf_token

try:
    from huggingface_hub import HfApi
except Exception as exc:  # pragma: no cover
    raise SystemExit(
        "Missing huggingface_hub. Install in your environment first:\n"
        "python -m pip install huggingface_hub"
    ) from exc


def _utc_compact() -> str:
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _safe_slug(value: str) -> str:
    out = "".join(ch.lower() if ch.isalnum() else "-" for ch in value.strip())
    while "--" in out:
        out = out.replace("--", "-")
    return out.strip("-") or "pack"


def _norm_key(path_value: str) -> str:
    p = (path_value or "").strip().strip('"').strip("'")
    p = p.replace("/", "\\")
    try:
        p = str(PureWindowsPath(p))
    except Exception:
        pass
    return p.lower()


def _iter_jsonl(path: Path) -> list[dict]:
    rows: list[dict] = []
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rows.append(json.loads(line))
    return rows


def _resolve_input_path(raw: str, source_root: Path) -> Path:
    p = Path(str(raw))
    if p.is_absolute():
        return p
    return (source_root / p).resolve()


def _portable_relpath(src_path: Path, source_root: Path) -> str:
    try:
        rel = src_path.resolve().relative_to(source_root.resolve())
        return rel.as_posix()
    except Exception:
        pass

    # Keep drive letter for absolute paths outside source_root.
    anchor = src_path.anchor
    if anchor:
        drive = anchor.replace("\\", "").replace("/", "").replace(":", "")
        try:
            tail = src_path.resolve().relative_to(src_path.anchor)
        except Exception:
            tail = src_path.name
        if isinstance(tail, Path):
            tail_str = tail.as_posix()
        else:
            tail_str = str(tail).replace("\\", "/")
        return f"{drive}/{tail_str}".strip("/")
    return src_path.name


def _rel_to(base: Path, p: Path) -> str:
    try:
        return p.resolve().relative_to(base.resolve()).as_posix()
    except Exception:
        return str(p).replace("\\", "/")


def _iter_dirs(root: Path) -> list[Path]:
    if not root.exists() or not root.is_dir():
        return []
    dirs = [root]
    dirs.extend(sorted((p for p in root.rglob("*") if p.is_dir()), key=lambda x: x.as_posix().lower()))
    return dirs


def _immediate_file_count(dir_path: Path) -> int:
    return sum(1 for p in dir_path.iterdir() if p.is_file())


def _collect_directory_file_counts(root: Path, base: Path, *, non_zero_only: bool = True) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for dir_path in _iter_dirs(root):
        file_count = _immediate_file_count(dir_path)
        if non_zero_only and file_count <= 0:
            continue
        rows.append(
            {
                "directory": _rel_to(base, dir_path),
                "file_count": int(file_count),
            }
        )
    rows.sort(key=lambda r: (-int(r["file_count"]), str(r["directory"]).lower()))
    return rows


def _validate_directory_file_limit(root: Path, base: Path, *, max_files_per_dir: int) -> list[dict[str, Any]]:
    offenders: list[dict[str, Any]] = []
    for dir_path in _iter_dirs(root):
        file_count = _immediate_file_count(dir_path)
        if file_count > max_files_per_dir:
            offenders.append(
                {
                    "directory": _rel_to(base, dir_path),
                    "file_count": int(file_count),
                }
            )
    offenders.sort(key=lambda r: (-int(r["file_count"]), str(r["directory"]).lower()))
    return offenders


def _apply_audio_dir_sharding(
    *,
    staging_root: Path,
    audio_root: Path,
    path_map: dict[str, str],
    max_files_per_dir: int,
    shard_prefix: str,
) -> dict[str, Any]:
    report: dict[str, Any] = {
        "max_files_per_dir": int(max_files_per_dir),
        "shard_prefix": shard_prefix,
        "directories_sharded": [],
    }
    if not audio_root.exists():
        return report

    reverse_map: dict[str, list[str]] = {}
    for src_key, dst_rel in path_map.items():
        nk = str(dst_rel).replace("\\", "/").strip("/")
        reverse_map.setdefault(nk, []).append(src_key)

    for dir_path in _iter_dirs(audio_root):
        files = [p for p in dir_path.iterdir() if p.is_file()]
        if len(files) <= max_files_per_dir:
            continue

        files_sorted = sorted(files, key=lambda p: (p.name.lower(), p.name))
        shard_rows: list[dict[str, Any]] = []
        shard_total = int(math.ceil(len(files_sorted) / float(max_files_per_dir)))
        for shard_idx in range(shard_total):
            start = shard_idx * max_files_per_dir
            end = min(start + max_files_per_dir, len(files_sorted))
            shard_name = f"{shard_prefix}_{shard_idx:04d}"
            shard_dir = dir_path / shard_name
            shard_dir.mkdir(parents=True, exist_ok=True)

            for src in files_sorted[start:end]:
                dst = shard_dir / src.name
                old_rel = _rel_to(staging_root, src).replace("\\", "/").strip("/")
                new_rel = _rel_to(staging_root, dst).replace("\\", "/").strip("/")
                shutil.move(str(src), str(dst))
                keys = reverse_map.pop(old_rel, [])
                if keys:
                    reverse_map.setdefault(new_rel, [])
                for key in keys:
                    path_map[key] = new_rel
                    reverse_map[new_rel].append(key)

            shard_rows.append(
                {
                    "shard": _rel_to(staging_root, shard_dir),
                    "file_count": int(end - start),
                }
            )

        report["directories_sharded"].append(
            {
                "directory": _rel_to(staging_root, dir_path),
                "files_before": int(len(files_sorted)),
                "shards_created": int(shard_total),
                "shards": shard_rows,
            }
        )

    return report


def _copy_audio_files(
    audio_paths: list[Path],
    source_root: Path,
    pack_root: Path,
) -> tuple[dict[str, str], list[str], int]:
    mapping: dict[str, str] = {}
    missing: list[str] = []
    copied = 0
    for src in audio_paths:
        key = _norm_key(str(src))
        if not src.exists():
            missing.append(str(src))
            continue
        rel = _portable_relpath(src, source_root)
        dst_rel = Path("audio") / rel
        dst = pack_root / dst_rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
        mapping[key] = dst_rel.as_posix()
        copied += 1
    return mapping, missing, copied


def _copy_entire_folder(
    folder: Path,
    source_root: Path,
    pack_root: Path,
    *,
    target_root: str = "audio",
) -> tuple[int, int]:
    copied = 0
    skipped = 0
    for src in folder.rglob("*"):
        if not src.is_file():
            continue
        rel = _portable_relpath(src, source_root)
        dst = pack_root / target_root / rel
        if dst.exists():
            skipped += 1
            continue
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
        copied += 1
    return copied, skipped


def _rewrite_manifest_rows(rows: list[dict], path_map: dict[str, str]) -> tuple[list[dict], int]:
    rewritten: list[dict] = []
    changed = 0
    for row in rows:
        out = dict(row)
        audio_path = str(row.get("audio_path", "") or "").strip()
        mapped = path_map.get(_norm_key(audio_path))
        if mapped:
            out["audio_path"] = mapped
            changed += 1
        rewritten.append(out)
    return rewritten, changed


def _write_jsonl(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")


def _rewrite_speaker_scores(src_csv: Path, dst_csv: Path, path_map: dict[str, str]) -> tuple[int, int]:
    dst_csv.parent.mkdir(parents=True, exist_ok=True)
    with src_csv.open("r", encoding="utf-8", newline="") as fin:
        reader = csv.DictReader(fin)
        fieldnames = list(reader.fieldnames or [])
        if "file" not in fieldnames:
            raise ValueError(f"speaker_scores CSV missing 'file' column: {src_csv}")
        rows = list(reader)

    changed = 0
    for row in rows:
        if None in row:
            row.pop(None, None)
        raw = str(row.get("file", "") or "")
        mapped = path_map.get(_norm_key(raw))
        if mapped:
            row["file"] = mapped
            changed += 1

    with dst_csv.open("w", encoding="utf-8", newline="") as fout:
        writer = csv.DictWriter(fout, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            clean_row = {k: row.get(k, "") for k in fieldnames}
            writer.writerow(clean_row)
    return len(rows), changed


def _collect_audio_paths_from_manifest(rows: list[dict], source_root: Path) -> list[Path]:
    out: list[Path] = []
    seen: set[str] = set()
    for row in rows:
        raw = str(row.get("audio_path", "") or "").strip()
        if not raw:
            continue
        p = _resolve_input_path(raw, source_root)
        key = _norm_key(str(p))
        if key in seen:
            continue
        seen.add(key)
        out.append(p)
    return out


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            chunk = f.read(1024 * 1024)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def _main() -> int:
    hf_hard_limit = 10_000
    ap = argparse.ArgumentParser(description="Create/upload private HF eval-pack for cloud testing")
    ap.add_argument("--repo-id", required=True, help="HF dataset repo, e.g. user/private-eval-pack")
    ap.add_argument("--repo-root", default=r"I:\whisper-acft", help="Repo root for .env fallback")
    ap.add_argument("--source-root", default=r"I:\\", help="Root used to resolve relative audio paths")
    ap.add_argument("--pack-tag", default="stage13-indian-accent-en", help="Human tag for this pack")
    ap.add_argument("--manifest", required=True, help="Input test manifest JSONL")
    ap.add_argument("--extra-manifest", action="append", default=[], help="Additional manifest(s) to include and rewrite")
    ap.add_argument("--speaker-scores-csv", required=True, help="Input speaker_sort_scores.csv")
    ap.add_argument("--others-manifest", default="", help="Optional OTHER-manifest JSONL")
    ap.add_argument("--extra-folder", action="append", default=[], help="Optional extra folder(s) to include under audio/")
    ap.add_argument("--private", type=int, default=1, help="Create repo as private if it doesn't exist")
    ap.add_argument("--revision", default="main", help="Branch/revision for upload")
    ap.add_argument("--dry-run", action="store_true", help="Build staging pack only, no upload")
    ap.add_argument("--keep-staging", action="store_true", help="Do not delete staging folder")
    ap.add_argument("--path-in-repo-prefix", default="eval_packs", help="Repo folder prefix")
    ap.add_argument("--max-files-per-dir", type=int, default=9000, help="Shard any destination directory above this many files")
    ap.add_argument("--shard-prefix", default="shard", help="Shard directory name prefix (e.g., shard -> shard_0000)")
    args = ap.parse_args()

    repo_root = Path(args.repo_root).resolve()
    source_root = Path(args.source_root).resolve()
    manifest_path = _resolve_input_path(args.manifest, repo_root)
    speaker_scores_path = _resolve_input_path(args.speaker_scores_csv, repo_root)
    others_manifest_path = _resolve_input_path(args.others_manifest, repo_root) if args.others_manifest else None
    extra_manifest_paths = [_resolve_input_path(p, repo_root) for p in (args.extra_manifest or []) if str(p).strip()]
    extra_folder_paths = [_resolve_input_path(p, repo_root) for p in (args.extra_folder or []) if str(p).strip()]
    shard_prefix = str(args.shard_prefix or "").strip()

    if not manifest_path.exists():
        raise SystemExit(f"Manifest not found: {manifest_path}")
    if not speaker_scores_path.exists():
        raise SystemExit(f"Speaker scores CSV not found: {speaker_scores_path}")
    if others_manifest_path and not others_manifest_path.exists():
        raise SystemExit(f"Others manifest not found: {others_manifest_path}")
    for mp in extra_manifest_paths:
        if not mp.exists():
            raise SystemExit(f"Extra manifest not found: {mp}")
    for fp in extra_folder_paths:
        if not fp.exists() or not fp.is_dir():
            raise SystemExit(f"Extra folder not found or not a directory: {fp}")
    if int(args.max_files_per_dir) <= 0:
        raise SystemExit("--max-files-per-dir must be > 0")
    if int(args.max_files_per_dir) > hf_hard_limit:
        raise SystemExit(f"--max-files-per-dir must be <= {hf_hard_limit}")
    if not shard_prefix:
        raise SystemExit("--shard-prefix must be non-empty")
    if "/" in shard_prefix or "\\" in shard_prefix:
        raise SystemExit("--shard-prefix must not contain path separators")

    pack_id = f"{_utc_compact()}__{_safe_slug(args.pack_tag)}"
    staging_root = repo_root / ".hf_eval_pack_staging" / pack_id
    if staging_root.exists():
        shutil.rmtree(staging_root, ignore_errors=True)
    staging_root.mkdir(parents=True, exist_ok=True)

    test_rows = _iter_jsonl(manifest_path)
    other_rows = _iter_jsonl(others_manifest_path) if others_manifest_path else []
    extra_rows_by_path: dict[Path, list[dict]] = {mp: _iter_jsonl(mp) for mp in extra_manifest_paths}
    audio_paths = _collect_audio_paths_from_manifest(test_rows, source_root)
    if other_rows:
        audio_paths.extend(_collect_audio_paths_from_manifest(other_rows, source_root))
    for extra_rows in extra_rows_by_path.values():
        audio_paths.extend(_collect_audio_paths_from_manifest(extra_rows, source_root))

    path_map, missing_audio, copied_count = _copy_audio_files(
        audio_paths=audio_paths,
        source_root=source_root,
        pack_root=staging_root,
    )
    extra_folder_stats: list[dict[str, Any]] = []
    for folder in extra_folder_paths:
        copied_folder, skipped_folder = _copy_entire_folder(
            folder=folder,
            source_root=source_root,
            pack_root=staging_root,
            target_root="audio",
        )
        extra_folder_stats.append(
            {
                "folder": str(folder),
                "copied_files": int(copied_folder),
                "skipped_existing_files": int(skipped_folder),
            }
        )
    sharding_report = _apply_audio_dir_sharding(
        staging_root=staging_root,
        audio_root=staging_root / "audio",
        path_map=path_map,
        max_files_per_dir=int(args.max_files_per_dir),
        shard_prefix=shard_prefix,
    )
    print(f"Audio files copied: {copied_count} | missing: {len(missing_audio)}")

    rewritten_test_rows, changed_test = _rewrite_manifest_rows(test_rows, path_map)
    test_manifest_out = staging_root / "manifests" / "pairs_manifest_stage13_test.jsonl"
    _write_jsonl(test_manifest_out, rewritten_test_rows)

    others_manifest_out = None
    changed_others = 0
    if other_rows:
        rewritten_other_rows, changed_others = _rewrite_manifest_rows(other_rows, path_map)
        others_manifest_out = staging_root / "manifests" / "others_manifest.jsonl"
        _write_jsonl(others_manifest_out, rewritten_other_rows)

    extra_manifest_outputs: list[dict[str, Any]] = []
    for extra_path, extra_rows in extra_rows_by_path.items():
        rewritten_extra_rows, changed_extra = _rewrite_manifest_rows(extra_rows, path_map)
        out_name = f"{extra_path.stem}.jsonl"
        out_path = staging_root / "manifests" / out_name
        _write_jsonl(out_path, rewritten_extra_rows)
        extra_manifest_outputs.append(
            {
                "source": str(extra_path),
                "output": f"manifests/{out_name}",
                "rows": int(len(extra_rows)),
                "paths_rewritten": int(changed_extra),
                "sha256": _sha256_file(out_path),
            }
        )

    speaker_scores_out = staging_root / "metadata" / "speaker_sort_scores.csv"
    speaker_rows, speaker_changed = _rewrite_speaker_scores(
        src_csv=speaker_scores_path,
        dst_csv=speaker_scores_out,
        path_map=path_map,
    )

    audio_file_counts = _collect_directory_file_counts(staging_root / "audio", base=staging_root, non_zero_only=True)
    hard_limit_offenders = _validate_directory_file_limit(
        staging_root,
        base=staging_root,
        max_files_per_dir=hf_hard_limit,
    )
    if hard_limit_offenders:
        top = "\n".join(
            f"  - {x['directory']}: {x['file_count']} files"
            for x in hard_limit_offenders[:10]
        )
        raise RuntimeError(
            "Pre-upload directory file-count validation failed. "
            f"Hub hard limit is {hf_hard_limit} files per directory.\n"
            f"Top offenders:\n{top}"
        )

    metadata = {
        "pack_id": pack_id,
        "pack_tag": args.pack_tag,
        "created_at_utc": datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
        "source": {
            "manifest": str(manifest_path),
            "extra_manifests": [str(p) for p in extra_manifest_paths],
            "speaker_scores_csv": str(speaker_scores_path),
            "others_manifest": str(others_manifest_path) if others_manifest_path else None,
            "source_root": str(source_root),
            "extra_folders": [str(p) for p in extra_folder_paths],
        },
        "counts": {
            "test_rows": len(test_rows),
            "other_rows": len(other_rows),
            "extra_manifest_rows_total": int(sum(len(v) for v in extra_rows_by_path.values())),
            "audio_paths_total": len(audio_paths),
            "audio_files_copied": copied_count,
            "audio_files_missing": len(missing_audio),
            "test_manifest_paths_rewritten": changed_test,
            "others_manifest_paths_rewritten": changed_others,
            "speaker_rows": speaker_rows,
            "speaker_paths_rewritten": speaker_changed,
        },
        "files": {
            "test_manifest": "manifests/pairs_manifest_stage13_test.jsonl",
            "speaker_scores_csv": "metadata/speaker_sort_scores.csv",
            "others_manifest": "manifests/others_manifest.jsonl" if others_manifest_out else None,
            "extra_manifests": [x["output"] for x in extra_manifest_outputs],
            "others_dir": "audio",
        },
        "checksums": {
            "test_manifest_sha256": _sha256_file(test_manifest_out),
            "speaker_scores_sha256": _sha256_file(speaker_scores_out),
        },
        "extra_manifest_outputs": extra_manifest_outputs,
        "extra_folder_copy_stats": extra_folder_stats,
        "layout": {
            "hf_hard_limit_files_per_dir": int(hf_hard_limit),
            "max_files_per_dir_requested": int(args.max_files_per_dir),
            "shard_prefix": shard_prefix,
            "directories_sharded": sharding_report["directories_sharded"],
            "audio_directory_file_counts": audio_file_counts,
        },
    }
    if others_manifest_out is not None:
        metadata["checksums"]["others_manifest_sha256"] = _sha256_file(others_manifest_out)
    if missing_audio:
        metadata["missing_audio_examples"] = missing_audio[:200]

    metadata_path = staging_root / "PACK_METADATA.json"
    metadata_path.write_text(json.dumps(metadata, indent=2, ensure_ascii=False), encoding="utf-8")

    if args.dry_run:
        print(f"[dry-run] Staging pack ready at: {staging_root}")
        return 0

    token = resolve_hf_token(repo_root, env_var="HF_TOKEN")
    if not token:
        env_values = parse_env_file(repo_root / ".env")
        token = env_values.get("HF_TOKEN", "").strip()
    if not token:
        raise SystemExit("HF token missing (set HF_TOKEN env var or add to .env)")
    os.environ["HF_TOKEN"] = token

    api = HfApi()
    api.create_repo(
        repo_id=args.repo_id,
        repo_type="dataset",
        private=bool(args.private),
        exist_ok=True,
        token=token,
    )

    path_in_repo = f"{args.path_in_repo_prefix.strip('/')}/{pack_id}"
    print(f"Uploading pack to dataset:{args.repo_id}/{path_in_repo}")
    commit = api.upload_folder(
        repo_id=args.repo_id,
        repo_type="dataset",
        folder_path=str(staging_root),
        path_in_repo=path_in_repo,
        token=token,
        revision=args.revision,
        commit_message=f"Add eval pack {pack_id}",
    )

    latest_ref = {
        "pack_id": pack_id,
        "pack_tag": args.pack_tag,
        "path_in_repo": path_in_repo,
        "repo_id": args.repo_id,
        "revision": args.revision,
        "updated_at_utc": datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
        "commit": getattr(commit, "oid", None),
        "files": metadata["files"],
    }
    latest_tmp = staging_root / "LATEST_PACK.json"
    latest_tmp.write_text(json.dumps(latest_ref, indent=2), encoding="utf-8")
    api.upload_file(
        repo_id=args.repo_id,
        repo_type="dataset",
        path_or_fileobj=str(latest_tmp),
        path_in_repo=f"{args.path_in_repo_prefix.strip('/')}/LATEST_PACK.json",
        token=token,
        revision=args.revision,
        commit_message=f"Update latest eval pack -> {pack_id}",
    )

    print(f"Upload complete. Repo: https://huggingface.co/datasets/{args.repo_id}")
    print(f"Pack path: {path_in_repo}")
    print(f"Latest pointer: {args.path_in_repo_prefix.strip('/')}/LATEST_PACK.json")

    if not args.keep_staging:
        shutil.rmtree(staging_root, ignore_errors=True)
        print("Staging folder removed.")
    else:
        print(f"Staging folder kept: {staging_root}")

    return 0


if __name__ == "__main__":
    raise SystemExit(_main())

param(
    [string]$RepoRoot = "I:\whisper-acft",
    [string]$RunsRoot = "I:\",
    [string]$CacheDir = "I:\hf_model_cache",
    [string]$InputCsv = "",
    [int]$MinSizeMB = 50,
    [switch]$CleanupLocal,
    [switch]$StopOnError
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Read-HfToken([string]$RepoRootPath) {
    if ($env:HF_TOKEN) { return $env:HF_TOKEN.Trim() }
    if ($env:HUGGINGFACE_TOKEN) { return $env:HUGGINGFACE_TOKEN.Trim() }
    $envFile = Join-Path $RepoRootPath ".env"
    if (-not (Test-Path -LiteralPath $envFile)) {
        return ""
    }
    foreach ($raw in Get-Content -Path $envFile -Encoding UTF8) {
        $line = $raw.Trim()
        if (-not $line -or $line.StartsWith("#") -or -not $line.Contains("=")) {
            continue
        }
        $parts = $line.Split("=", 2)
        $key = $parts[0].Trim()
        if ($key -notin @("HF_TOKEN", "HUGGINGFACE_TOKEN")) {
            continue
        }
        $value = $parts[1].Trim().Trim('"').Trim("'")
        if ($value) { return $value }
    }
    return ""
}

function Get-LatestDryRunCsv([string]$RepoRootPath) {
    $reportDir = Join-Path $RepoRootPath "hf_tier1_reports"
    if (-not (Test-Path -LiteralPath $reportDir)) {
        throw "hf_tier1_reports does not exist: $reportDir"
    }
    $latest = Get-ChildItem -Path $reportDir -File -Filter "hf_tier1_archive_*.csv" |
        Sort-Object LastWriteTime -Descending |
        Select-Object -First 1
    if (-not $latest) {
        throw "No report CSV found under $reportDir"
    }
    return $latest.FullName
}

function Get-ModelFilesForRun([string]$RunPath, [long]$MinBytes) {
    $extSet = @(".safetensors", ".bin", ".pt", ".pth", ".ckpt", ".gguf", ".ggml", ".onnx")
    if (-not (Test-Path -LiteralPath $RunPath)) {
        return @()
    }
    $items = Get-ChildItem -Path $RunPath -Recurse -File -ErrorAction SilentlyContinue |
        Where-Object { $extSet -contains $_.Extension.ToLowerInvariant() -and $_.Length -ge $MinBytes }
    return @($items)
}

function New-PointerFiles(
    [string]$RunPath,
    [string]$RunFolder,
    [string]$RepoId,
    [string]$Revision,
    [string]$CacheDirPath,
    [array]$ModelFiles,
    [array]$DeletedRelPaths,
    [int]$MinSize
) {
    $pointerPath = Join-Path $RunPath "MODEL_POINTER.json"
    $readmePath = Join-Path $RunPath "MODEL_POINTER_README.md"
    $urlPath = Join-Path $RunPath "HF_MODEL_REPO.url"

    $archivedFiles = @()
    foreach ($f in $ModelFiles) {
        $rel = $f.FullName.Substring($RunPath.Length).TrimStart('\') -replace '\\','/'
        $archivedFiles += [pscustomobject]@{
            abs_path = $f.FullName
            rel_path = $rel
            size_bytes = [int64]$f.Length
        }
    }

    $pointer = [pscustomobject]@{
        pointer_version = "1.0"
        created_at_utc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
        run_folder = $RunFolder
        local_run_path = $RunPath
        repo_id = $RepoId
        repo_url = "https://huggingface.co/$RepoId"
        repo_type = "model"
        private = $true
        revision = $Revision
        cache_strategy = [pscustomobject]@{
            mode = "hybrid"
            central_cache_dir = $CacheDirPath
            local_restore_dir_default = (Join-Path $RunPath "restored_model")
        }
        archive_policy = [pscustomobject]@{
            min_size_mb = $MinSize
            cleanup_local_enabled = [bool]$CleanupLocal
            extensions = @(".safetensors", ".bin", ".pt", ".pth", ".ckpt", ".gguf", ".ggml", ".onnx")
        }
        archived_files = $archivedFiles
        deleted_local_files = $DeletedRelPaths
    }
    $pointer | ConvertTo-Json -Depth 8 | Set-Content -Path $pointerPath -Encoding UTF8

    $restoreCmd = 'python "I:\whisper-acft\tools\hf_tier1_restore_from_pointer.py" --pointer "' + $pointerPath + '" --cache-dir "' + $CacheDirPath + '" --local-dir "' + (Join-Path $RunPath "restored_model") + '"'
    $readmeText = @(
        "# Model Pointer",
        "",
        "- Repo: https://huggingface.co/$RepoId",
        "- Revision: $Revision",
        "- Privacy: private",
        "- Pointer JSON: MODEL_POINTER.json",
        "",
        "## Restore (hybrid cache)",
        "",
        '```powershell',
        $restoreCmd,
        '```'
    ) -join [Environment]::NewLine
    Set-Content -Path $readmePath -Value $readmeText -Encoding UTF8

    @"
[InternetShortcut]
URL=https://huggingface.co/$RepoId
"@ | Set-Content -Path $urlPath -Encoding UTF8
}

if (-not $InputCsv) {
    $InputCsv = Get-LatestDryRunCsv -RepoRootPath $RepoRoot
}
if (-not (Test-Path -LiteralPath $InputCsv)) {
    throw "Input CSV not found: $InputCsv"
}

$hfToken = Read-HfToken -RepoRootPath $RepoRoot
if (-not $hfToken) {
    throw "HF token not found in env or .env"
}
$env:HF_TOKEN = $hfToken
$username = (hf auth whoami).Trim()
if (-not $username) {
    throw "Failed to resolve HF username via hf auth whoami"
}

$rows = @(Import-Csv -Path $InputCsv | Where-Object { $_.status -eq "dry_run" -and $_.repo_id })
$session = Get-Date -Format "yyyyMMdd_HHmmss"
$reportDir = Join-Path $RepoRoot "hf_tier1_reports"
New-Item -ItemType Directory -Path $reportDir -Force | Out-Null

$results = New-Object System.Collections.Generic.List[object]
$minBytes = [int64]$MinSizeMB * 1024 * 1024

$i = 0
foreach ($row in $rows) {
    $i++
    $runFolder = $row.run_folder
    $repoId = $row.repo_id
    $runPath = Join-Path $RunsRoot $runFolder
    $status = "unknown"
    $note = ""
    $fileCount = 0
    $uploadBytes = [int64]0
    $deletedBytes = [int64]0
    $revision = ""

    try {
        Write-Host ("[{0}/{1}] {2}" -f $i, $rows.Count, $runFolder)
        if (-not (Test-Path -LiteralPath $runPath)) {
            $status = "missing_run_folder"
            $note = $runPath
            throw "Run folder missing: $runPath"
        }

        $files = @(Get-ModelFilesForRun -RunPath $runPath -MinBytes $minBytes)
        $fileCount = @($files).Count
        if ($fileCount -gt 0) {
            $measure = $files | Measure-Object -Property Length -Sum
            $uploadBytes = [int64]($measure.Sum)
        } else {
            $uploadBytes = [int64]0
        }

        if ($fileCount -eq 0) {
            $status = "skip_no_files"
            $note = "No model files >= $MinSizeMB MB"
            try {
                $apiUri = "https://huggingface.co/api/models/$repoId"
                $headers = @{ Authorization = "Bearer $hfToken" }
                $repoInfo = Invoke-RestMethod -Uri $apiUri -Headers $headers -Method Get
                $revision = [string]$repoInfo.sha
                $sibCount = @($repoInfo.siblings).Count
                if ($sibCount -gt 1) {
                    New-PointerFiles -RunPath $runPath -RunFolder $runFolder -RepoId $repoId -Revision ($revision ? $revision : "main") -CacheDirPath $CacheDir -ModelFiles @() -DeletedRelPaths @() -MinSize $MinSizeMB
                    $status = "pointer_only_no_local_files"
                    $note = "Local model files absent; pointer generated from existing remote repo"
                }
            } catch {
                $note = "No local files and remote repo not usable: $($_.Exception.Message)"
            }
            $results.Add([pscustomobject]@{
                run_folder = $runFolder
                repo_id = $repoId
                status = $status
                file_count = $fileCount
                upload_bytes = $uploadBytes
                deleted_bytes = $deletedBytes
                revision = $revision
                note = $note
            })
            continue
        }

        hf repo create $repoId --private --exist-ok | Out-Host
        foreach ($f in $files) {
            $rel = $f.FullName.Substring($runPath.Length).TrimStart('\') -replace '\\','/'
            hf upload $repoId $f.FullName $rel --repo-type model --commit-message "Archive $runFolder : $rel" | Out-Host
        }

        $apiUri = "https://huggingface.co/api/models/$repoId"
        $headers = @{ Authorization = "Bearer $hfToken" }
        $repoInfo = Invoke-RestMethod -Uri $apiUri -Headers $headers -Method Get
        $revision = [string]$repoInfo.sha
        $remoteFiles = @{}
        foreach ($s in $repoInfo.siblings) {
            if ($s.rfilename) { $remoteFiles[$s.rfilename] = $true }
        }
        $missing = @()
        foreach ($f in $files) {
            $rel = $f.FullName.Substring($runPath.Length).TrimStart('\') -replace '\\','/'
            if (-not $remoteFiles.ContainsKey($rel)) {
                $missing += $rel
            }
        }
        if ($missing.Count -gt 0) {
            $status = "verify_failed"
            $note = "Missing on remote: $($missing.Count)"
            throw "Remote verification failed for $runFolder"
        }

        $deletedRel = @()
        if ($CleanupLocal) {
            foreach ($f in $files) {
                if (Test-Path -LiteralPath $f.FullName) {
                    Remove-Item -LiteralPath $f.FullName -Force
                    $deletedBytes += [int64]$f.Length
                    $deletedRel += ($f.FullName.Substring($runPath.Length).TrimStart('\') -replace '\\','/')
                }
            }
        }

        New-PointerFiles -RunPath $runPath -RunFolder $runFolder -RepoId $repoId -Revision ($revision ? $revision : "main") -CacheDirPath $CacheDir -ModelFiles $files -DeletedRelPaths $deletedRel -MinSize $MinSizeMB
        $status = "uploaded"
    } catch {
        if ($status -eq "unknown") {
            $status = "error"
            $note = $_.Exception.Message
        } elseif (-not $note) {
            $note = $_.Exception.Message
        }
        Write-Warning ("Failed run {0}: {1}" -f $runFolder, $note)
        if ($StopOnError) {
            $results.Add([pscustomobject]@{
                run_folder = $runFolder
                repo_id = $repoId
                status = $status
                file_count = $fileCount
                upload_bytes = $uploadBytes
                deleted_bytes = $deletedBytes
                revision = $revision
                note = $note
            })
            break
        }
    }

    $results.Add([pscustomobject]@{
        run_folder = $runFolder
        repo_id = $repoId
        status = $status
        file_count = $fileCount
        upload_bytes = $uploadBytes
        deleted_bytes = $deletedBytes
        revision = $revision
        note = $note
    })
}

$outCsv = Join-Path $reportDir ("hf_tier1_repo_by_repo_" + $session + ".csv")
$outJson = Join-Path $reportDir ("hf_tier1_repo_by_repo_" + $session + ".json")
$results | Export-Csv -Path $outCsv -NoTypeInformation -Encoding UTF8

$summary = [pscustomobject]@{
    created_at_utc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
    input_csv = $InputCsv
    repo_root = $RepoRoot
    runs_root = $RunsRoot
    min_size_mb = $MinSizeMB
    cleanup_local = [bool]$CleanupLocal
    total_runs = $rows.Count
    uploaded_runs = (@($results | Where-Object { $_.status -eq "uploaded" })).Count
    failed_runs = (@($results | Where-Object { $_.status -in @("error", "verify_failed", "missing_run_folder") })).Count
    bytes_deleted = [int64](($results | Measure-Object -Property deleted_bytes -Sum).Sum)
    results = $results
}
$summary | ConvertTo-Json -Depth 8 | Set-Content -Path $outJson -Encoding UTF8

$registryPath = Join-Path $RepoRoot "HF_PRIVATE_TIER1_REGISTRY.json"
$existing = @{}
if (Test-Path -LiteralPath $registryPath) {
    try {
        $existing = Get-Content -Path $registryPath -Raw -Encoding UTF8 | ConvertFrom-Json -AsHashtable
    } catch {
        $existing = @{}
    }
}
if (-not $existing.ContainsKey("entries")) {
    $existing["entries"] = @()
}
$map = @{}
foreach ($entry in $existing["entries"]) {
    if ($entry.run_folder) { $map[$entry.run_folder] = $entry }
}
foreach ($r in $results) {
    if (-not $r.repo_id) { continue }
    $map[$r.run_folder] = [ordered]@{
        run_folder = $r.run_folder
        repo_id = $r.repo_id
        status = $r.status
        revision = $r.revision
        updated_at_utc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
    }
}
$existing["updated_at_utc"] = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
$existing["repo_prefix"] = "Whisper-acft"
$existing["username"] = $username
$existing["min_size_mb"] = $MinSizeMB
$existing["entries"] = @($map.Values | Sort-Object run_folder)
$existing["latest_report_json"] = $outJson
$existing["latest_report_csv"] = $outCsv

if (-not $existing.ContainsKey("report_history")) {
    $existing["report_history"] = @()
}
$existing["report_history"] = @($existing["report_history"] + @([ordered]@{
    created_at_utc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
    json = $outJson
    csv = $outCsv
    cleanup_local = [bool]$CleanupLocal
})) | Select-Object -Last 200

$existing | ConvertTo-Json -Depth 10 | Set-Content -Path $registryPath -Encoding UTF8

Write-Host "Done"
Write-Host "CSV: $outCsv"
Write-Host "JSON: $outJson"
Write-Host "Registry: $registryPath"
$results | Group-Object status | Sort-Object Name | ForEach-Object { Write-Host ("{0}: {1}" -f $_.Name, $_.Count) }

#!/usr/bin/env python3
"""Transcribe target/other audio in target-mix eval JSON via Groq and update references.

This script:
  - Loads evaluation_per_sample_predictions_targetmix_sweep.json (array)
  - Finds unique target_audio_path + other_audio_path entries
  - Transcribes each unique audio with Groq STT
  - Updates target_reference / other_reference (or adds new fields)

It reuses groq_transcribe_local_utils.py for the actual Groq request plumbing.
"""

from __future__ import annotations

import argparse
import json
import os
import random
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

from dotenv import load_dotenv

from groq_transcribe_local_utils import (  # type: ignore
    GROQ_TRANSCRIBE_URL,
    Key,
    KeyPool,
    groq_transcribe_requests,
)


def canonical_audio_key(p: str) -> str:
    if not p:
        return ""
    return os.path.normpath(p).replace("\\", "/").lower()


def _skip_ws(text: str, i: int) -> int:
    n = len(text)
    while i < n and text[i].isspace():
        i += 1
    return i


def _best_effort_parse_array(text: str) -> List[Any]:
    items: List[Any] = []
    dec = json.JSONDecoder()
    i = _skip_ws(text, 0)
    if i >= len(text) or text[i] != "[":
        return items
    i += 1
    while True:
        i = _skip_ws(text, i)
        if i >= len(text):
            break
        if text[i] == "]":
            break
        try:
            obj, j = dec.raw_decode(text, i)
            items.append(obj)
            i = _skip_ws(text, j)
            if i < len(text) and text[i] == ",":
                i += 1
                continue
            if i < len(text) and text[i] == "]":
                break
        except json.JSONDecodeError:
            break
    return items


def load_json(path: Path) -> Any:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        print(f"[warn] JSONDecodeError: {e.msg} at line {e.lineno} col {e.colno}")
        text = path.read_text(encoding="utf-8", errors="replace")
        items = _best_effort_parse_array(text)
        if items:
            print(f"[warn] Proceeding with best-effort parse: {len(items)} items recovered.")
            return items
        raise


def write_json(path: Path, obj: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    tmp.replace(path)


def load_cache_jsonl(path: Path) -> Dict[str, Dict[str, Any]]:
    cache: Dict[str, Dict[str, Any]] = {}
    if not path.exists():
        return cache
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            key = obj.get("canonical") or canonical_audio_key(obj.get("path", ""))
            if key:
                cache[key] = obj
    return cache


def append_cache_jsonl(path: Path, obj: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(obj, ensure_ascii=False) + "\n")
        f.flush()


def _load_keys_from_env_names(env_names: Sequence[str]) -> List[Key]:
    keys: List[Key] = []
    for name in env_names:
        v = os.environ.get(name)
        if v:
            # Support comma-separated keys
            if "," in v:
                for i, key_value in enumerate(v.split(",")):
                    key_value = key_value.strip()
                    if key_value:
                        keys.append(Key(name=f"{name}_{i+1}", value=key_value))
            else:
                keys.append(Key(name=name, value=v))
    return keys


def _split_csv(value: str) -> List[str]:
    return [x.strip() for x in (value or "").split(",") if x.strip()]


def _load_keys_from_env_file(env_path: Path, env_names: Sequence[str]) -> List[Key]:
    keys: List[Key] = []
    if not env_path.exists():
        return keys

    continuation_key: Optional[str] = None
    for line in env_path.read_text(encoding="utf-8").splitlines():
        raw = line.strip()
        if not raw or raw.startswith("#"):
            continuation_key = None
            continue

        if "=" in raw:
            name, val = raw.split("=", 1)
            name = name.strip()
            val = val.strip()
            if val and len(val) >= 2 and val[0] == val[-1] and val[0] in ("'", '"'):
                val = val[1:-1]
            if name in env_names:
                for v in _split_csv(val):
                    keys.append(Key(name=f"{name}_file_{len(keys)+1}", value=v))
                if name == "GROQ_API_KEYS" and val.rstrip().endswith(","):
                    continuation_key = name
                else:
                    continuation_key = None
            else:
                continuation_key = None
            continue

        if continuation_key == "GROQ_API_KEYS":
            for v in _split_csv(raw):
                keys.append(Key(name=f"{continuation_key}_file_{len(keys)+1}", value=v))
        else:
            continuation_key = None

    return keys


def _load_keys_from_file(keys_file: Path) -> List[Key]:
    keys: List[Key] = []
    for line in keys_file.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" in line:
            name, val = line.split("=", 1)
            name = name.strip()
            val = val.strip()
        else:
            name = f"key{len(keys)+1}"
            val = line
        if val:
            keys.append(Key(name=name, value=val))
    return keys


def extract_text(resp_json: Dict[str, Any]) -> str:
    if not isinstance(resp_json, dict):
        return ""
    text = resp_json.get("text")
    if isinstance(text, str) and text.strip():
        return text.strip()
    segs = resp_json.get("segments")
    if isinstance(segs, list):
        parts = []
        for s in segs:
            if isinstance(s, dict):
                t = s.get("text")
                if isinstance(t, str) and t.strip():
                    parts.append(t.strip())
        if parts:
            return " ".join(parts).strip()
    return ""


def transcribe_one(
    audio_path: Path,
    pool: KeyPool,
    *,
    model: str,
    language: Optional[str],
    prompt: Optional[str],
    temperature: float,
    response_format: str,
    timestamp_granularities: Sequence[str],
    timeout_s: float,
    max_attempts: int,
    min_interval_s: float,
    jitter_s: float,
    last_request_by_key: Dict[str, float],
) -> Tuple[str, Dict[str, Any], str]:
    attempts = 0
    while True:
        attempts += 1
        key = pool.get()
        if min_interval_s > 0:
            now = time.time()
            last_t = last_request_by_key.get(key.name, 0.0)
            to_wait = (last_t + min_interval_s) - now
            if to_wait > 0:
                time.sleep(to_wait + random.uniform(0, jitter_s))
        try:
            r = groq_transcribe_requests(
                audio_path=audio_path,
                api_key=key.value,
                model=model,
                language=language,
                prompt=prompt,
                temperature=temperature,
                response_format=response_format,
                timestamp_granularities=timestamp_granularities,
                timeout_s=timeout_s,
            )
            last_request_by_key[key.name] = time.time()

            if r.status_code == 429:
                retry_after = r.headers.get("retry-after")
                ra_s = float(retry_after) if retry_after and retry_after.replace(".", "", 1).isdigit() else None
                pool.cooldown(key.name, retry_after=ra_s)
                if attempts < max_attempts:
                    continue
                r.raise_for_status()

            if 500 <= r.status_code < 600:
                pool.cooldown(key.name, retry_after=10)
                if attempts < max_attempts:
                    continue
                r.raise_for_status()

            r.raise_for_status()

            if response_format == "text":
                text = (r.text or "").strip()
                resp_json = {"text": text}
            else:
                resp_json = r.json()
                text = extract_text(resp_json)

            return key.name, resp_json, text
        except Exception:
            pool.cooldown(key.name, retry_after=15)
            if attempts < max_attempts:
                continue
            raise


def build_audio_list(data: List[Dict[str, Any]]) -> List[str]:
    paths: List[str] = []
    for obj in data:
        if not isinstance(obj, dict):
            continue
        p_t = obj.get("target_audio_path")
        p_o = obj.get("other_audio_path")
        if isinstance(p_t, str) and p_t.strip():
            paths.append(p_t.strip())
        if isinstance(p_o, str) and p_o.strip():
            paths.append(p_o.strip())
    return paths


def build_reference_map(data: List[Dict[str, Any]]) -> Dict[str, str]:
    ref_map: Dict[str, str] = {}
    for obj in data:
        if not isinstance(obj, dict):
            continue
        for path_key, ref_key in (
            ("target_audio_path", "target_reference"),
            ("other_audio_path", "other_reference"),
        ):
            p = obj.get(path_key)
            ref = obj.get(ref_key)
            if isinstance(p, str) and isinstance(ref, str):
                p = p.strip()
                ref = ref.strip()
                if not p or not ref:
                    continue
                k = canonical_audio_key(p)
                if not k:
                    continue
                existing = ref_map.get(k)
                if not existing or len(ref) > len(existing):
                    ref_map[k] = ref
    return ref_map


def build_prompt(reference: Optional[str], user_prompt: Optional[str], max_chars: int) -> str:
    lines = [
        "You are a transcription engine. Return the best possible transcript with proper punctuation and casing.",
    ]
    if user_prompt:
        lines.append(f"Additional instructions: {user_prompt.strip()}")
    if reference:
        ref = reference.strip()
        if max_chars and max_chars > 0 and len(ref) > max_chars:
            ref = ref[:max_chars].rstrip()
        lines.append("Reference transcript (may contain errors):")
        lines.append(ref)
    return "\n\n".join(lines).strip()


def apply_updates(
    data: List[Dict[str, Any]],
    cache: Dict[str, Dict[str, Any]],
    *,
    mode: str,
    target_field: str,
    other_field: str,
) -> Tuple[int, int]:
    updated_t = 0
    updated_o = 0
    for obj in data:
        if not isinstance(obj, dict):
            continue

        # Skip metadata entries
        if obj.get("__meta__"):
            continue

        t_path = obj.get("target_audio_path")
        if isinstance(t_path, str):
            key = canonical_audio_key(t_path)
            entry = cache.get(key)
            text = entry.get("text") if entry else None
            if isinstance(text, str) and text.strip():
                if mode == "replace":
                    obj["target_reference"] = text
                else:
                    obj[target_field] = text
                updated_t += 1

        o_path = obj.get("other_audio_path")
        if isinstance(o_path, str):
            key = canonical_audio_key(o_path)
            entry = cache.get(key)
            text = entry.get("text") if entry else None
            if isinstance(text, str) and text.strip():
                if mode == "replace":
                    obj["other_reference"] = text
                else:
                    obj[other_field] = text
                updated_o += 1
    return updated_t, updated_o


def _unique_env_paths(paths: Sequence[Path]) -> List[Path]:
    seen = set()
    out: List[Path] = []
    for p in paths:
        try:
            rp = p.resolve()
        except Exception:
            rp = p
        key = str(rp).lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(p)
    return out


def main() -> None:

    ap = argparse.ArgumentParser()
    ap.add_argument("--input_json", type=Path, required=True)
    ap.add_argument("--out_json", type=Path, default=None)
    ap.add_argument("--inplace", action="store_true", default=True)
    ap.add_argument("--cache_jsonl", type=Path, default=None)

    ap.add_argument("--mode", choices=["add", "replace"], default="replace",
                    help="add: write *_reference_groq fields, replace: overwrite *_reference fields")
    ap.add_argument("--target_field", default="target_reference_groq")
    ap.add_argument("--other_field", default="other_reference_groq")

    ap.add_argument("--model", default="whisper-large-v3-turbo")
    ap.add_argument("--language", default="en")
    ap.add_argument("--prompt", default=None)
    ap.add_argument("--use_reference_prompt", action="store_true", default=True)
    ap.add_argument("--no_reference_prompt", action="store_false", dest="use_reference_prompt")
    ap.add_argument("--prompt_max_chars", type=int, default=600,
                    help="Max chars of reference transcript to include in prompt (0 = no limit)")
    ap.add_argument("--temperature", type=float, default=0.0)
    ap.add_argument("--response_format", default="verbose_json", choices=["json", "verbose_json", "text"])
    ap.add_argument("--timestamp_granularities", nargs="*", default=["segment"],
                    help="Use with verbose_json. Options: word, segment")
    ap.add_argument("--timeout_s", type=float, default=float(os.getenv("GROQ_TIMEOUT_S", "300.0")))
    ap.add_argument("--max_attempts", type=int, default=5)

    ap.add_argument("--max_rpm", type=float, default=float(os.getenv("GROQ_MAX_RPM", "18.0")))
    ap.add_argument("--jitter_s", type=float, default=float(os.getenv("GROQ_JITTER_S", "0.25")))

    ap.add_argument("--api_key", default=None)
    ap.add_argument("--key_env_names", nargs="*", default=["GROQ_API_KEY", "GROQ_API_KEYS"])
    ap.add_argument("--keys_file", type=Path, default=None)
    ap.add_argument("--env_file", type=Path, default=None,
                    help="Optional .env file to load Groq keys from (in addition to CWD/script .env).")

    args = ap.parse_args()

    if not args.input_json.exists():
        raise SystemExit(f"Missing input_json: {args.input_json}")

    if args.out_json is None:
        args.out_json = args.input_json.with_name(args.input_json.stem + "_groq" + args.input_json.suffix)

    if args.inplace:
        args.out_json = args.input_json

    if args.cache_jsonl is None:
        args.cache_jsonl = args.input_json.with_name(args.input_json.stem + "_groq_cache.jsonl")

    # Load .envs (explicit, CWD, script dir) without overriding existing env vars
    env_candidates: List[Path] = []
    if args.env_file:
        env_candidates.append(args.env_file)
    env_candidates.append(Path(".env"))
    env_candidates.append(Path(__file__).with_name(".env"))
    env_files = _unique_env_paths(env_candidates)
    for p in env_files:
        if p.exists():
            load_dotenv(dotenv_path=p, override=False)

    # Keys
    keys: List[Key] = []
    if args.api_key:
        keys.append(Key("api_key", args.api_key))
    if args.keys_file:
        keys.extend(_load_keys_from_file(args.keys_file))
    keys.extend(_load_keys_from_env_names(args.key_env_names))
    for env_path in env_files:
        keys.extend(_load_keys_from_env_file(env_path, args.key_env_names))

    # De-dup by value
    seen = set()
    uniq: List[Key] = []
    for k in keys:
        if k.value in seen:
            continue
        seen.add(k.value)
        uniq.append(k)
    keys = uniq

    if not keys:
        raise SystemExit("No Groq API keys found. Set GROQ_API_KEY or pass --keys_file / --api_key.")

    pool = KeyPool(keys)

    if args.timestamp_granularities and args.response_format != "verbose_json":
        print("NOTE: timestamp_granularities requires response_format=verbose_json on Groq; forcing.")
        args.response_format = "verbose_json"

    # Load data
    data = load_json(args.input_json)
    if not isinstance(data, list):
        raise SystemExit("Expected input_json to be a JSON array.")

    # Build unique audio list
    dict_rows = [x for x in data if isinstance(x, dict)]
    all_paths = build_audio_list(dict_rows)
    uniq_map: Dict[str, str] = {}
    for p in all_paths:
        k = canonical_audio_key(p)
        if k and k not in uniq_map:
            uniq_map[k] = p

    print(f"Found {len(all_paths)} audio references ({len(uniq_map)} unique).")

    ref_map = build_reference_map(dict_rows)

    # Load cache
    cache = load_cache_jsonl(args.cache_jsonl)
    print(f"Loaded cache: {len(cache)} entries from {args.cache_jsonl}")

    # Transcribe missing
    min_interval = 60.0 / args.max_rpm if args.max_rpm and args.max_rpm > 0 else 0.0
    last_request_by_key: Dict[str, float] = {}
    ok = 0
    skipped = 0
    failed = 0

    for canonical_key, path_str in uniq_map.items():
        ref_text = ref_map.get(canonical_key)
        prompt_used = args.prompt
        if args.use_reference_prompt:
            prompt_used = build_prompt(ref_text, args.prompt, int(args.prompt_max_chars))

        cached = cache.get(canonical_key) or {}
        if cached.get("text") and cached.get("prompt_effective") == prompt_used:
            skipped += 1
            continue

        audio_path = Path(path_str)
        if not audio_path.exists():
            failed += 1
            print(f"[missing] {path_str}")
            continue

        try:
            key_name, resp_json, text = transcribe_one(
                audio_path,
                pool,
                model=args.model,
                language=args.language,
                prompt=prompt_used,
                temperature=args.temperature,
                response_format=args.response_format,
                timestamp_granularities=args.timestamp_granularities,
                timeout_s=args.timeout_s,
                max_attempts=args.max_attempts,
                min_interval_s=min_interval,
                jitter_s=args.jitter_s,
                last_request_by_key=last_request_by_key,
            )
            ok += 1
            entry = {
                "canonical": canonical_key,
                "path": path_str,
                "text": text,
                "request": {
                    "endpoint": GROQ_TRANSCRIBE_URL,
                    "model": args.model,
                    "language": args.language,
                    "prompt": prompt_used,
                    "temperature": args.temperature,
                    "response_format": args.response_format,
                    "timestamp_granularities": list(args.timestamp_granularities),
                    "api_key_name": key_name,
                },
                "groq_response": resp_json,
                "prompt_effective": prompt_used,
                "ts": time.time(),
            }
            append_cache_jsonl(args.cache_jsonl, entry)
            cache[canonical_key] = entry
            print(f"[ok] {audio_path.name} -> {len(text)} chars")
        except Exception as e:
            failed += 1
            print(f"[fail] {path_str} :: {repr(e)}")

    # Apply updates
    updated_t, updated_o = apply_updates(
        [x for x in data if isinstance(x, dict)],
        cache,
        mode=args.mode,
        target_field=args.target_field,
        other_field=args.other_field,
    )

    # Write output
    if args.inplace:
        backup = args.input_json.with_suffix(args.input_json.suffix + ".bak")
        if not backup.exists():
            backup.write_text(args.input_json.read_text(encoding="utf-8"), encoding="utf-8")
        write_json(args.out_json, data)
    else:
        write_json(args.out_json, data)

    print("\nDone")
    print(f"Transcribed OK: {ok} | Skipped (cache): {skipped} | Failed: {failed}")
    print(f"Updated target refs: {updated_t} | Updated other refs: {updated_o}")
    print(f"Output: {args.out_json}")
    print(f"Cache: {args.cache_jsonl}")


if __name__ == "__main__":
    main()
